  .blueprint::after, .hero-facts::after, .site-section::after, .doc-section::after { display: none; }
}

/* Pen rules replace the remaining machine-straight table and fact dividers. */
.hero-facts > div { position: relative; border-color: transparent !important; }
.hero-facts > div::after {
  content: ''; position: absolute; bottom: -4px; left: 0; right: 0; height: 8px;
  background: var(--sketch-ink); opacity: .55; pointer-events: none;
