        url('../img/sketch-rail.svg') right top / 14px 800px repeat-y;
}
@media print, (forced-colors: active) {
  body::before { display: none; }
}
.docs-content { position: relative; }
@media (min-width: 901px) {
  .docs-content::before {
    content: ''; position: absolute; inset: 0 auto 0 -7px; width: 14px;
    background: var(--sketch-ink); opacity: .65; pointer-events: none;
    -webkit-mask: url('../img/sketch-rail.svg') center / 100% 100%;
    mask: url('../img/sketch-rail.svg') center / 100% 100%;
  }
}

/* Two slightly different passes of the pen around a sheet. */
.blueprint, .hero-facts {
  position: relative; border: 1px solid var(--sketch-faint);
  border-radius: 2px 4px 1px 3px / 3px 1px 4px 2px;
    box-shadow: none;
}
.blueprint::after, .hero-facts::after {
  content: ''; display: block; position: absolute; inset: -3px;
  background: var(--sketch-ink);
  -webkit-mask: url('../img/sketch-frame.svg') center / 100% 100% no-repeat;
  mask: url('../img/sketch-frame.svg') center / 100% 100% no-repeat;
  pointer-events: none;
}
.blueprint .corner { display: block; opacity: .45; }
.blueprint .corner::before { transform: rotate(3deg); }
.blueprint .corner::after { transform: rotate(-3deg); }
.hero-facts { overflow: visible; }
.hero-facts dt, .table th, .spec dt, .doc-section .kicker,
.doc-section .section-heading > div > .eyebrow:first-child {
  font-family: var(--font-mono); font-size: 11px; letter-spacing: .06em;
  text-transform: uppercase;
}
.hero-facts dt { color: var(--muted); }
.hero-facts > div { border-color: var(--sketch-faint); }


/* Short graphite swatches under headings, with the original indigo ink. */
.section-heading h2::after, .doc-section h1::after,
.contribute-page h1::after, #mv-hero::after {
  content: ''; display: block; width: 94px; height: 9px; margin-top: 14px;
  background: currentColor; opacity: .65;
  -webkit-mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
  mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
}
#mv-hero::after, .home-page .section-heading h2::after { margin-inline: auto; }
.btn, .pathsw label, .tag { border-radius: 2px; }

.btn, .pathsw label { box-shadow: 2px 2px 0 var(--sketch-faint); }
.btn-ghost { box-shadow: none; }

.card.blueprint::before {
  content: ''; display: block; position: absolute; inset: auto 10px 5px auto;
  width: 45px; height: 10px; background: var(--sketch-hatch); pointer-events: none;
}

.card.blueprint:hover { border-color: var(--color-accent); }
.table th { border-bottom-color: var(--sketch-ink); }
.table td { border-bottom-color: var(--sketch-faint); }

/* SVG geometry alone gets a small ink irregularity; labels and leaders stay crisp. */
[data-ref="anatomyRef"] svg defs > g { filter: url(#mv-pen); }
[data-ref="anatomyRef"] svg use { stroke-linejoin: round; stroke-linecap: round; }

@media (forced-colors: active) {
  .site-section__inner, .docs-content, .entire-footer, .blueprint, .hero-facts { background-image: none; }
  .blueprint::after, .hero-facts::after, .site-section::after, .doc-section::after { display: none; }
}

/* Pen rules replace the remaining machine-straight table and fact dividers. */
.hero-facts > div { position: relative; border-color: transparent !important; }
.hero-facts > div::after {
  content: ''; position: absolute; bottom: -4px; left: 0; right: 0; height: 8px;
  background: var(--sketch-ink); opacity: .55; pointer-events: none;
  -webkit-mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
  mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
}
.hero-facts > div::before {
  content: ''; position: absolute; top: 0; bottom: 0; right: -4px; width: 8px;
  background: var(--sketch-ink); opacity: .55; pointer-events: none;
  -webkit-mask: url('../img/sketch-rail.svg') center / 100% 100% no-repeat;
  mask: url('../img/sketch-rail.svg') center / 100% 100% no-repeat;
}
.hero-facts > div:nth-child(3n)::before { display: none; }
.hero-facts > div:nth-last-child(-n+3)::after { display: none; }
@media (max-width:700px) {
  .hero-facts > div:nth-child(3n)::before { display: block; }
  .hero-facts > div:nth-child(2n)::before { display: none; }
  .hero-facts > div:nth-last-child(3)::after { display: block; }
}

.table th, .table td { position: relative; border-bottom-color: transparent; }
/* Keep decorative rules inside cells so they do not enlarge scroll regions. */
.table th::after, .table td::after {
  content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 6px;
  background: var(--sketch-ink); opacity: .45; pointer-events: none;
  -webkit-mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
  mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
}
.table th::after { opacity: .9; }
@media (forced-colors: active) {
  .site-header__inner::before, .site-section__inner::before, .docs-layout::before,
  .docs-content::before, .entire-footer::before, .site-header::after,
  .hero-facts > div::before, .hero-facts > div::after { display: none; }
}

/* Original background and brand colors come exclusively from entire.css.
   Sparse, fixed stroke clusters shade the rails; no page-wide grain or tint. */
.section-sketch-number {
  position: absolute; top: 24px; left: 32px; width: 44px; height: 57px;
  color: var(--muted); opacity: .48; transform: rotate(-5deg);
  pointer-events: none;
}
.section-sketch-number svg { display: block; width: 100%; height: 100%; }
.rail-shading {
  position: absolute; width: min(260px, 30%); height: 52px;
  color: var(--color-text); opacity: .15; pointer-events: none;
  background: currentColor;
  -webkit-mask: var(--shading) center / 100% 100% no-repeat;
  mask: var(--shading) center / 100% 100% no-repeat;
}
.rail-shading--top { top: 0; right: 1px; }
.rail-shading--bottom { bottom: 0; left: 1px; transform: rotate(180deg); }
.site-section:nth-child(2) .rail-shading { width: min(185px, 26%); height: 38px; }
.site-section:nth-child(3) .rail-shading { height: 65px; width: min(310px, 30%); }
.site-section:nth-child(4) .rail-shading { height: 43px; }
.site-section:nth-child(5) .rail-shading { width: min(205px, 27%); }
@media(max-width:700px) {
  .section-sketch-number { left: 18px; top: 12px; width: 29px; height: 38px; }
  .rail-shading { max-height: 30px; }
}
@media(forced-colors:active) { .rail-shading { display:none; } }

.site-section:nth-child(1) .rail-shading { --shading: url('../img/rail-shading-1.svg'); }
.site-section:nth-child(2) .rail-shading { --shading: url('../img/rail-shading-2.svg'); }
.site-section:nth-child(3) .rail-shading { --shading: url('../img/rail-shading-3.svg'); }
.site-section:nth-child(4) .rail-shading { --shading: url('../img/rail-shading-4.svg'); }
.site-section:nth-child(5) .rail-shading { --shading: url('../img/rail-shading-5.svg'); }
.site-section:nth-child(6) .rail-shading { --shading: url('../img/rail-shading-6.svg'); }

/* Horizontal pen strokes taper inward from a few other rail corners. */
.rail-shading-horizontal {
  position: absolute; top: 1px; right: 1px; width: min(240px, 30%); height: 105px;
  background: var(--color-text); opacity: .15; pointer-events: none;
  -webkit-mask: url('../img/rail-shading-horizontal.svg') center / 100% 100% no-repeat;
  mask: url('../img/rail-shading-horizontal.svg') center / 100% 100% no-repeat;
}
.site-section:nth-child(3) .rail-shading-horizontal { width: min(180px, 25%); height: 78px; }
.site-section:nth-child(5) .rail-shading-horizontal { top: auto; bottom: 1px; transform: scaleY(-1); }
@media(max-width:700px) { .rail-shading-horizontal { width: 100px; max-height: 65px; } }
@media(forced-colors:active) { .rail-shading-horizontal { display: none; } }

/* Documentation has no full-width final section rule, so its footer owns it. */
.documentation-page .site-footer { position: relative; }
.documentation-page .site-footer::before {
  content: ''; position: absolute; top: -11px; left: 0; right: 0; height: 22px;
  background: var(--sketch-ink); pointer-events: none;
  -webkit-mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
  mask: url('../img/sketch-rule.svg') center / 100% 100% no-repeat;
}

/* Studies occupy only the measured spare height of an existing grid column.
   Absolute positioning means they never create a row or change section height. */
.study-host { position: relative; }
.margin-study {
  display: none; position: absolute; bottom: 0; pointer-events: none;
  background: var(--study) center / contain no-repeat;
  mix-blend-mode: multiply; opacity: .45;
  width: min(100%, 480px); height: min(var(--study-space), 215px);
}
.margin-study--wiring { left: 0; --study: url('../img/studies/wiring-ink.png'); }
/* The shorter Build one introduction leaves room for the print study. */
.build-study { display: none; }
@media(min-width:800px) {
  .build-study {
    display: block; position: absolute; right: 32px; top: 24px;
    width: clamp(140px, 15vw, 185px); aspect-ratio: 1;
    background: url('../img/studies/print-plate-ink.png') center / contain no-repeat;
    mix-blend-mode: multiply; opacity: .42; pointer-events: none;
  }
}
@media(min-width:1000px) {
  .margin-study[data-fits] { display: block; }
}
@media(forced-colors:active), print { .margin-study, .build-study { display: none; } }

/* Safari's root overscroll clips fixed decorations. Bounce the content in an
   overflow scrollport instead, leaving the rail layer on the stationary body. */
html.safari-framed-scroll { height: 100%; overflow: hidden; }
.safari-framed-scroll body { height: 100%; overflow: hidden; }
.safari-page-scrollport { height: 100%; overflow: auto; overscroll-behavior-y: contain; }
.safari-page-scrollport:focus { outline: none; }
@media print {
  html.safari-framed-scroll, .safari-framed-scroll body,
  .safari-page-scrollport { height: auto; overflow: visible; }
}
/* Static adaptation of ../entire.io/website: shared brand assets, neutral
   surfaces, indigo accents, bordered rails, and footer. No runtime dependency. */
@font-face{font-family:"Entire Headline";src:url('../fonts/entire-headline-semibold.woff2') format('woff2');font-weight:100 900;font-display:swap}
@font-face{font-family:"Entire Mono";src:url('../fonts/entire-mono-regular.woff2') format('woff2');font-weight:400;font-display:swap}
@font-face{font-family:"Entire Mono";src:url('../fonts/entire-mono-bold.woff2') format('woff2');font-weight:700;font-display:swap}
:root{
  --font-heading:"Entire Headline",ui-sans-serif,system-ui,sans-serif;
  --font-body:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --font-mono:"Entire Mono",ui-monospace,SFMono-Regular,monospace;
  --color-bg:#f6f6f6;--color-surface:#fcfcfc;--color-text:#0f0f0f;
  --color-neutral-100:#f2f2f2;--color-neutral-800:#1e1e1e;
  --color-accent:rgb(55 42 172);--color-accent-100:#e0e7ff;--color-accent-700:var(--color-accent);--color-accent-800:#312e81;
  --color-divider:rgb(0 0 0 / .1);--muted:#707070;
  --rule:var(--color-divider);--rule-ink:var(--color-divider);--link:var(--color-accent-700);
  --help-ink:#93345d;--help-border:#93345d;--help-bg:#fbeaf1;
  --radius-md:8px;--radius-lg:12px;
  color-scheme:light;
}
@media(prefers-color-scheme:dark){
  :root{
    --help-ink:#f5b5cf;--help-border:#c8799d;--help-bg:#3b2431;
    --color-bg:#161616;--color-surface:#1c1c1c;--color-text:#f3f3f3;
    --color-neutral-100:#222;--color-neutral-800:#d9d9d9;
    --color-accent:rgb(124 134 255);--color-accent-100:#25234a;--color-accent-700:var(--color-accent);--color-accent-800:#c7d2fe;
    --color-divider:rgb(255 255 255 / .1);--muted:#949494;--link:var(--color-accent-700);color-scheme:dark;
  }
}

/* Typography follows website/src/styles.css: site-h1, home-hero-title,
   text-site-title, text-site-body and text-site-label. */
body { font: 400 16px/1.5 var(--font-body); }
::selection { background: var(--color-accent); color: var(--color-bg); }
a, button { transition: color .15s, background-color .15s; }
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 4px; }
[id] { scroll-margin-top: 96px; }
h1 { font: 500 32px/32px var(--font-heading); letter-spacing: 0; }
h2 { font: 500 24px/28px var(--font-heading); letter-spacing: 0; }
h3, h4 { font: 600 16px/20px var(--font-body); letter-spacing: 0; }
p { margin-top: 0; }
.eyebrow, .kicker {
  font: 600 12px/20px var(--font-mono); letter-spacing: .08em;
  text-transform: uppercase; color: var(--muted); margin: 0 0 8px;
}

/* Shared header: Entire logo, right-aligned navigation, 64px desktop rail. */
.site-header {
  position: sticky; top: 0; z-index: 50; border-bottom: 1px solid var(--rule);
  background: color-mix(in srgb, var(--color-bg) 95%, transparent);
}
.site-header__inner {
  max-width: 1280px; min-height: 63px; margin: auto; padding: 12px 24px;
  display: grid; align-items: center; grid-template-columns: 1fr auto; gap: 24px;
}
.site-navigation > summary { cursor: pointer; list-style: none; border: 1px solid var(--rule); border-radius: 8px; padding: 6px; background: var(--color-surface); }
.site-navigation > summary::-webkit-details-marker { display: none; }
.site-navigation > summary svg { display: block; }
@media(min-width:768px) { .has-site-js .site-navigation > summary { display: none; } }
.site-identity, .entire-home { display: flex; align-items: center; }
.entire-home { color: var(--color-text); width: fit-content; }
.entire-logo { display: block; width: auto; height: 24px; }
.site-nav { display: flex; align-items: center; gap: 12px; font-size: 14px; }
.site-nav a { padding: 6px 10px; border-radius: 8px; white-space: nowrap; text-decoration: none; color: var(--muted); }
.site-nav a:hover, .site-nav a[aria-current] { color: var(--color-text); background: var(--color-neutral-100); }

/* Full-width rules and a shared inner frame, matching Entire's SiteSection. */
.landing-content { margin: 0; padding: 0; }
.site-section { border-bottom: 1px solid var(--rule); }
.site-section__inner { max-width: 1280px; margin: auto; padding: 48px 32px; }
.section-heading { display: block; }
.home-page .section-heading > div > h2 { margin-bottom: 24px !important; }
.home-page .section-heading > div > p:first-child,
.home-page .section-heading > div > h2 { text-align: center; }
.home-page .section-heading > div > h2 + p { margin-inline: auto !important; text-align: center; }
.home-page .site-section:nth-child(3) .site-section__inner,
.home-page .site-section:nth-child(5) .site-section__inner { background: var(--color-neutral-100); }
.home-page .site-section:first-child .site-section__inner { padding-top: 64px; }
/* Entire uses neutral section headings and accented eyebrow labels.
   The Marvin hero title also uses the accent, as requested. */
main h1, main h2, main h3, main h4 { color: var(--color-text); }
.section-eyebrow { color: var(--color-accent); }
.card-kicker { color: var(--muted); }
#mv-hero { text-align: center; color: var(--color-accent); }
.hero-intro { max-width: 640px; margin: 20px auto 0; font-size: 20px; line-height: 28px; text-align: center; }
.hero-facts {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  max-width: 800px; margin: 40px auto 0; border: 1px solid var(--rule);
  border-radius: 8px; overflow: hidden; background: var(--color-surface);
}
.hero-facts > div { padding: 16px 20px; border-right: 1px solid var(--rule); }
.hero-facts > div:nth-child(3n) { border-right: 0; }
.hero-facts > div:nth-child(n+4) { border-top: 1px solid var(--rule); }
.hero-facts dt { font: 400 11px/16px var(--font-mono); text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.hero-facts dd { margin: 6px 0 0; font-size: 14px; line-height: 20px; }

/* Plain HTML documentation shell: quiet hierarchy, readable navigation,
   and a native disclosure on narrow screens rather than hidden links. */
.docs-layout {
  max-width: 1280px; margin: auto; display: grid;
  grid-template-columns: 240px minmax(0, 1fr); align-items: start;
}
.docs-sidebar {
  position: sticky; top: 64px; padding: 32px 20px; max-height: calc(100dvh - 64px);
  overflow-y: auto; scrollbar-width: thin; font-size: 14px;
}
.docs-menu > summary { display: none; }
.docs-sidebar__title { display: block; padding: 0 12px 12px; font-size: 14px; font-weight: 600; color: var(--color-text); text-decoration: none; }
.docs-sidebar__group { margin: 24px 12px 8px; font-size: 12px; font-weight: 500; color: var(--muted); }
.docs-sidebar ul { list-style: none; padding: 0; margin: 0; }
.docs-sidebar li { margin: 2px 0; }
.docs-sidebar li > a { display: block; padding: 8px 12px; border-radius: 6px; color: var(--muted); line-height: 20px; text-decoration: none; }
.docs-sidebar li > a:hover { background: var(--color-neutral-100); color: var(--color-text); }
.docs-sidebar li > a[aria-current="page"] { color: var(--color-accent-700); background: var(--color-accent-100); font-weight: 500; }
.docs-sidebar .docs-sidebar__subnav { border-left: 1px solid var(--rule); margin: 10px 0 16px 18px; padding-left: 8px; }
.docs-sidebar__subnav li > a { font-size: 13px; padding: 5px 12px; }
.docs-sidebar__subnav a[aria-current="location"] { color: var(--color-accent-700); background: var(--color-neutral-100); }
.docs-content { min-width: 0; border-left: 1px solid var(--rule); padding: 0 40px; }
.doc-section { padding: 40px 0; border-bottom: 1px solid var(--rule); }
.doc-section:first-child { padding-top: 48px; }
.doc-section:last-child { border-bottom: 0; }
.doc-section .kicker { font: 400 12px/20px var(--font-body); letter-spacing: 0; text-transform: none; color: var(--muted); margin-bottom: 12px; }
.doc-section .section-heading > div > h1 + p,
.contribute-page h1 + p { font-size: 16px !important; line-height: 24px !important; }
.contribute-page main > nav[aria-label="On this page"] { top: 64px !important; }
.contribute-page main > nav[aria-label="On this page"] ol {
  max-width: 1280px; margin: auto !important; padding: 12px 32px !important;
  flex-wrap: nowrap !important; overflow-x: auto; white-space: nowrap;
  font: 400 14px/20px var(--font-body) !important; letter-spacing: 0 !important; text-transform: none !important;
}

/* Controls and technical content use the same type and surface hierarchy. */
.btn { border-radius: 8px; font: 500 14px/20px var(--font-body); letter-spacing: 0; text-transform: none; min-height: 40px; padding: 10px 16px; box-shadow: 0 1px 2px rgb(0 0 0 / .04); }
.btn-primary { background: var(--color-accent); border-color: var(--color-accent); color: var(--color-bg); }
.btn-primary:hover { background: var(--color-accent-800); border-color: var(--color-accent-800); color: var(--color-bg); }
.btn-secondary { background: var(--color-surface); color: var(--color-text); border-color: var(--rule); }
.btn-ghost { box-shadow: none; }
.blueprint { border-radius: 8px; background: var(--color-surface); }
.blueprint .corner { display: none; }
.duotone { border-radius: 6px; }
.hero-video__media { border-radius: 6px; }
.duotone::after, .duotone::before { display: none; }
.duotone img, .duotone video { filter: none; mix-blend-mode: normal; }
.card, .dialog, .input, .seg { border-radius: 8px; }
.tag { border-radius: 5px; font-size: 11px; white-space: nowrap; overflow-wrap: normal; }
.table { font-size: 13px; line-height: 20px; }
.table th { font: 500 12px/18px var(--font-body); letter-spacing: 0; text-transform: none; }
.table td { padding: 10px 7px; overflow-wrap: anywhere; }
.table th { padding: 10px 7px; }
.pathsw label { border-radius: 8px; font: 500 14px/20px var(--font-body); padding: 10px 14px; letter-spacing: 0; }
.pathsw legend { font: 500 14px/20px var(--font-body); text-transform: none; letter-spacing: 0; }
.pathsw label .n { font-size: 11px; letter-spacing: 0; text-transform: none; }
.steps > li { grid-template-columns: 32px minmax(0,1fr); gap: 16px; padding: 24px 0; }
.steps > li > .n { font: 400 14px/24px var(--font-mono); letter-spacing: 0; color: var(--muted); }
.steps > li[data-when] > .n { color: var(--muted); }
.steps h3 { font: 600 16px/24px var(--font-body); letter-spacing: 0; }
.spec dt { font: 500 12px/20px var(--font-body); letter-spacing: 0; text-transform: none; }

/* Shared footer credit. */
.site-footer { border-top: 1px solid var(--rule); }
.home-page .site-footer, .contribute-page .site-footer { border-top: 0; }
.entire-footer { max-width: 1280px; margin: auto; padding: 32px; font-size: 14px; line-height: 20px; text-align: center; color: var(--muted); }
.entire-footer a { color: inherit; text-underline-offset: 3px; }
.entire-footer a:hover { color: var(--color-text); }
@media(min-width:768px) {
  h1 { font-size: 40px; line-height: 40px; }
  #mv-hero { font-size: 48px; line-height: 48px; }
}
@media(min-width:1280px) {
  .site-header__inner, .site-section__inner, .docs-layout, .entire-footer { border-inline: 1px solid var(--rule); }
}
@media(max-width:1000px) {
  .docs-layout { grid-template-columns: 210px minmax(0,1fr); }
  .docs-content { padding-inline: 24px; }
}
@media(max-width:900px) {
  .docs-layout { display: block; }
  .docs-sidebar { top: 64px; z-index: 30; max-height: calc(100dvh - 64px); padding: 0; border-bottom: 1px solid var(--rule); background: var(--color-bg); }
  .docs-menu > summary { display: flex; justify-content: space-between; padding: 14px 24px; cursor: pointer; font-weight: 500; list-style: none; }
  .docs-menu > summary::-webkit-details-marker { display: none; }
  .docs-menu[open] > summary span { transform: rotate(180deg); }
  .docs-menu nav { padding: 0 12px 20px; }
  .docs-sidebar__title { display: none; }
  .docs-content { border-left: 0; }
  .docs-sidebar__group:first-of-type { margin-top: 8px; }
  [id] { scroll-margin-top: 140px; }
}
@media(max-width:700px) {
  .site-section__inner { padding: 40px 20px; }
  .home-page .site-section:first-child .site-section__inner { padding-top: 40px; }
  .hero-intro { font-size: 18px; line-height: 26px; }
  .hero-facts { grid-template-columns: repeat(2,minmax(0,1fr)); margin-top: 32px; }
  .hero-facts > div { padding: 14px; border: 0; }
  .hero-facts > div:nth-child(odd) { border-right: 1px solid var(--rule); }
  .hero-facts > div:nth-child(n+3) { border-top: 1px solid var(--rule); }
  .docs-sidebar { top: 64px; max-height: calc(100dvh - 64px); }
  .docs-content { padding-inline: 20px; }
  .doc-section:first-child { padding-top: 32px; }
  .docs-menu > summary { padding-inline: 20px; }
  .contribute-page main > nav[aria-label="On this page"] { top: 64px !important; }
  .contribute-page main > nav[aria-label="On this page"] ol { padding-inline: 20px !important; }
  [id] { scroll-margin-top: 140px; }
  .entire-footer { padding: 28px 20px; }
}
@media(prefers-reduced-motion:reduce) { a, button { transition: none; } }

@media(max-width:767px) {
  .site-header__inner { display: flex; justify-content: space-between; padding: 12px 20px; height: 63px; }
  .site-navigation > summary { display: flex; align-items: center; justify-content: center; width: 36px; height: 36px; }
  .site-nav { position: fixed; inset: 64px 0 0; flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 32px; padding: 20px 16px; overflow-y: auto; background: var(--color-bg); }
  .site-nav a { padding: 0 8px; font-size: 16px; line-height: 24px; font-weight: 600; color: var(--color-text); }
  .site-nav a[aria-current] { background: transparent; }
}

.table-scroll, .diagram-scroll { max-width: 100%; min-width: 0; overflow-x: auto; scrollbar-width: thin; }
.table-scroll:focus-visible, .diagram-scroll:focus-visible { outline-offset: -2px; }
.doc-section .section-heading > div > .eyebrow:first-child { font: 400 12px/20px var(--font-body); text-transform: none; letter-spacing: 0; }
@media(max-width:600px) {
  .table-scroll--wide > table { min-width: 480px; }
  .table-scroll td { overflow-wrap: normal; }
  .diagram-scroll > svg { min-width: 880px; }
}

.is-scrollable::before { content: "Scroll horizontally to see more →"; display: block; position: sticky; left: 0; width: fit-content; max-width: 100%; padding: 8px 0; font: 400 12px/18px var(--font-body); color: var(--muted); }

.command-token { font: 500 24px/28px var(--font-mono); color: var(--color-text); }

/* Let the video determine the shared row height; fit the complete diagram
   into the space above its caption instead of letting SVG ratio grow the row. */
.motion-comparison {
  display: grid; grid-template-columns: minmax(0, 1fr);
  gap: clamp(20px, 3vw, 48px); margin-top: clamp(28px, 4vw, 56px);
}
.head-envelope { display: flex; flex-direction: column; }
.head-envelope > svg { height: auto; }
@media (min-width: 768px) {
  .motion-comparison { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .head-envelope { contain: size; }
  .head-envelope > svg { flex: 1; min-height: 0; height: 0; }
}

/* Section state is separate from the current documentation page. */
.docs-sidebar__subnav a[aria-current="location"] { font-weight: 500; }
.contribute-page main section[id] { scroll-margin-top: 140px; }
.contribute-page nav[aria-label="On this page"] a {
  display: block; padding: 4px 8px; border-radius: 6px;
  color: var(--muted); text-decoration: none;
}
.contribute-page nav[aria-label="On this page"] a:hover { color: var(--color-text); }
.contribute-page nav[aria-label="On this page"] a[aria-current="location"] {
  color: var(--color-accent-700); background: var(--color-accent-100);
}

/* Share the four content rows so wrapped badges and copy cannot stagger the cards. */
.build-paths {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr));
  column-gap: clamp(14px, 2.5vw, 28px);
  row-gap: var(--space-2);
  margin-bottom: clamp(24px, 3.5vw, 40px);
}
.build-paths > .card {
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 4;
}
.build-path-label {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  gap: 8px 12px;
  min-height: 22px;
}
.version-notice {
  margin: 0;
  padding: 0.65rem max(1rem, calc((100vw - 1280px) / 2 + 1rem));
  border-bottom: 1px solid var(--rule-ink);
  background: var(--color-accent-100);
  color: var(--color-text);
  font-size: 0.78rem;
  line-height: 1.45;
}

.version-notice a {
  color: inherit;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.18em;
}
"}

