.analog-stick[aria-disabled=true]{opacity:.55;cursor:not-allowed}
.analog-stick i{position:absolute;width:var(--stick-knob);height:var(--stick-knob);transform:translate(-50%,-50%);will-change:left,top;transition:left .05s,top .05s}

