 .remote-header .eyebrow{display:none}.remote-header h2{font-size:21px}
 .remote-header .icon-button{width:44px;height:44px}
 .remote-status{display:inline-block;width:10px;height:10px;padding:0;border:0;background:currentColor;overflow:hidden;text-indent:20px;box-shadow:0 0 0 4px color-mix(in srgb,currentColor 12%,transparent)}
