/* Keep page changes calm: opacity and transform are composited, so they do not
   move surrounding content while data or a modal becomes available. */
.page-enter{animation:page-enter 260ms cubic-bezier(.2,.75,.25,1) both}
.login-page.page-enter .login-copy{animation:content-enter 360ms 45ms cubic-bezier(.2,.75,.25,1) both}.login-page.page-enter .login-illustration{animation:content-enter 420ms 95ms cubic-bezier(.2,.75,.25,1) both}
.app-layout.page-enter .sidebar,.app-layout.page-enter .workspace-header,.app-layout.page-enter .conversation-inner,.app-layout.page-enter .composer-region{animation:content-enter 300ms cubic-bezier(.2,.75,.25,1) both}.app-layout.page-enter .conversation-inner{animation-delay:55ms}.app-layout.page-enter .composer-region{animation-delay:90ms}
.dialog{animation:dialog-enter 180ms cubic-bezier(.2,.8,.2,1) both}.dialog::backdrop{animation:backdrop-enter 180ms ease-out both}.dialog.is-closing{animation:dialog-exit 180ms cubic-bezier(.4,0,1,1) both;pointer-events:none}.dialog.is-closing::backdrop{animation:backdrop-exit 180ms ease-in both}
@keyframes page-enter{from{opacity:0}to{opacity:1}}@keyframes content-enter{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}@keyframes dialog-enter{from{opacity:0;transform:translateY(10px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes dialog-exit{from{opacity:1;transform:translateY(0) scale(1)}to{opacity:0;transform:translateY(6px) scale(.985)}}@keyframes backdrop-enter{from{opacity:0}to{opacity:1}}@keyframes backdrop-exit{from{opacity:1}to{opacity:0}}

/* Initial layout is revealed as one stable surface. Reserving both scrollbar
   gutters keeps centered conversation content fixed as async data settles. */
.conversation-scroll{scrollbar-gutter:stable both-edges}
.page-enter{animation-duration:200ms;animation-timing-function:ease-out}
.login-page.page-enter .login-copy,.login-page.page-enter .login-illustration,.app-layout.page-enter .sidebar,.app-layout.page-enter .workspace-header,.app-layout.page-enter .conversation-inner,.app-layout.page-enter .composer-region{animation:none}

