test('repository explorer renders provenance, safe snippets, pagination and recoverable errors',async({page})=>{
 // Recorded UI responses exercise rendering; this does not claim a live Entire service test.
 await page.route('**/api/settings',async route=>{const response=await route.fetch();await route.fulfill({json:{...await response.json(),entireState:'connected',entireAvailable:true,repositories:[{id:'entire_test',name:'test/repository',capabilities:['summary','source','search','history']}]}});});
 await page.route(/\/api\/conversations\/[^/]+$/,async route=>{if(route.request().method()!=='GET'){await route.continue();return;}const response=await route.fetch();const data=await response.json();await route.fulfill({json:{...data,conversation:{...data.conversation,repositoryId:'entire_test'}}});});
 let reads=0;await page.route('**/api/conversations/*/repository/read',async route=>{reads++;if(reads===3){await route.fulfill({status:429,json:{error:{code:'ENTIRE_RATE_LIMITED',message:'Entire is limiting requests. Wait a moment and retry.'}}});return;}await route.fulfill({json:{kind:'repository',repositoryId:'entire_test',title:'Recorded repository evidence',revision:'a'.repeat(40),summary:'Test evidence, not a live read.',source:'entire',files:[],fetchedAt:Date.now(),nextPage:reads===1?2:null,evidence:[{id:'hit',label:'src/main.ts',origin:'git',revision:'a'.repeat(40),path:'src/main.ts',lineStart:3,lineEnd:3,excerpt:'<img src=x onerror="window.compromised=true">'}]}});});
 await fresh(page);await page.getByLabel('Explore repository',{exact:true}).click();await page.getByLabel('Search repository',{exact:true}).fill('retry');await page.getByRole('button',{name:'Search',exact:true}).click();await page.locator('.evidence summary').click();await expect(page.locator('.evidence pre')).toContainText('<img');await expect(page.locator('.evidence img')).toHaveCount(0);await expect(page.locator('.evidence')).toContainText('Committed source');await audit(page);await page.screenshot({path:'work/screenshots/repository-explorer.png',fullPage:true});await page.getByRole('button',{name:'Next page',exact:true}).click();await page.getByRole('button',{name:'Repository overview'}).click();await expect(page.getByRole('alert')).toContainText('limiting requests');await page.getByLabel('Close dialog').click();await expect(page.getByLabel('Message Marvin')).toBeVisible();
});
