/* Entire's visual system, shared by every app surface. Functional layout and
   mobile controller sizing remain in style.css; this layer owns presentation. */
@font-face {
  font-family: "Entire Headline";
  src: url('/fonts/entire-headline-semibold.woff2') format('woff2');
  font-weight: 100 900;
  font-display: swap;
}
@font-face {
  font-family: "Entire Mono";
  src: url('/fonts/entire-mono-regular.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Entire Mono";
  src: url('/fonts/entire-mono-bold.woff2') format('woff2');
  font-weight: 700;
  font-display: swap;
}
:root {
  font: 400 16px/1.5 var(--marvin-font-body);
  color: var(--marvin-text);
  background: var(--marvin-bg);
  -webkit-font-smoothing: antialiased;
}
::selection { background: var(--marvin-accent); color: var(--marvin-action-text); }
h1, h2, h3, h4 { letter-spacing: 0; }
h1, h2, h3 { font-family: var(--marvin-font-heading); }
h3, .dialog-header h2, .login-form h2, .setup-content > h3 {
  font-size: 24px;
  line-height: 28px;
  font-weight: 500;
}
h4 { font-size: 16px; line-height: 20px; font-weight: 600; }
p { line-height: 1.5; }
.wordmark, .login-header .wordmark {
  font: 500 24px/28px var(--marvin-font-heading);
  letter-spacing: 0;
}
.eyebrow, .welcome .eyebrow, .settings-pane > .eyebrow {
  font: 400 11px/16px var(--marvin-font-code);
  letter-spacing: .06em;
  color: var(--marvin-accent);
}
.login-copy h1, .welcome h1 {
  font: 500 40px/40px var(--marvin-font-heading);
  letter-spacing: 0;
}
.login-copy h1 { font-size: 48px; line-height: 48px; }
.login-description { font-size: 20px; line-height: 28px; }
.welcome > p:last-child { font-size: 16px; line-height: 24px; }

/* 1280px outer rails and a 64px header match Entire's SiteSection geometry. */
.login-page, .app-layout { max-width: 1280px; margin-inline: auto; }
.login-page { padding-inline: 32px; }
.login-header { height: 64px; flex-shrink: 0; }
.login-grid { gap: 48px; padding-block: 64px; }
.login-footer { min-height: 64px; height: auto; gap: 16px; padding-block: 16px; }
.workspace-header { height: 64px; padding-inline: 24px; background: var(--marvin-bg); }
.sidebar { padding-top: 0; }
.sidebar-brand { height: 64px; flex-shrink: 0; margin-bottom: 24px; }
.login-illustration { border-radius: var(--marvin-radius-panel); }
.login-illustration::before, .login-illustration::after { display: none; }
.remote-header { height: 64px; padding-inline: max(24px, calc((100% - 1232px) / 2)); }
@media (min-width: 1280px) {
  .login-page, .app-layout { border-inline: 1px solid var(--marvin-rule); }
  .remote-screen::before {
    content: ''; position: absolute; inset: 0;
    width: 1280px; max-width: 100%; margin-inline: auto;
    border-inline: 1px solid var(--marvin-rule); pointer-events: none;
  }
}

/* Quiet raised surfaces, indigo actions, and consistent controls. */
.button, .new-chat, .icon-button, .send-button, .settings-nav button,
.history-list button, .sidebar-bottom > a, .sidebar-bottom > button,
.field input, .field select, .repository-panel select, .eye-design-card select,
.voice-action, .voice-end, .remote-speech-composer {
  border-radius: var(--marvin-radius-control);
}
.button { min-height: var(--marvin-target-size); font-size: 14px; font-weight: 500; line-height: 20px; }
.button.primary:hover { filter: none; background: var(--marvin-accent-hover); }
.button.secondary { box-shadow: 0 1px 2px rgb(0 0 0 / .04); }
.dialog, .setting-card, .repo-card, .connect-card, .suggestions button,
.composer, .voice-composer, .voice-presence, .instructions, .remote-speech,
.entire-auth-step, .connector-fallback, .autonomous-switch {
  border-radius: var(--marvin-radius-panel);
}
.dialog { background: var(--panel); }
.dialog-header { background: var(--panel); min-height: 64px; }
.settings-nav { background: var(--marvin-bg); }
.settings-nav button.active, .history-list button.active {
  color: var(--marvin-link); background: var(--marvin-accent-subtle);
}
.suggestions button, .connect-card, .composer, .voice-presence, .voice-composer,
.remote-speech { background: var(--panel); border-color: var(--marvin-rule); box-shadow: none; }
.suggestions button:hover { transform: none; background: var(--hover); border-color: var(--marvin-accent); }
.composer:focus-within, .voice-composer:focus-within {
  border-color: var(--marvin-accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--marvin-accent) 12%, transparent);
}
.badge, .body-status, .remote-status, .live-badge { border-radius: 5px; }
.badge { font-size: 11px; line-height: 16px; }
.badge.small { font-size: 10px; }
.remote-speech h3 { font-family: var(--marvin-font-body); letter-spacing: 0; }
.marvin-face.large { transform: none; box-shadow: none; border-radius: var(--marvin-radius-panel); }
.connection-logo { font-family: var(--marvin-font-body); border-radius: var(--marvin-radius-control); }
.markdown h1, .markdown h2, .markdown h3 { line-height: 1.25; }
/* Text on a sunken surface needs more contrast than the default muted label. */
.user-message .message-label, .avatar { color: var(--marvin-text); }

@media (max-width: 767px) {
  .login-page {
    padding-inline: max(20px, env(safe-area-inset-left)) max(20px, env(safe-area-inset-right));
  }
  .login-grid { padding-block: 40px; gap: 32px; }
  .login-copy h1, .welcome h1 { font-size: 32px; line-height: 32px; }
  .login-description { font-size: 18px; line-height: 26px; }
  .workspace-header {
    height: calc(64px + env(safe-area-inset-top));
    padding-inline: max(12px, env(safe-area-inset-left)) max(12px, env(safe-area-inset-right));
  }
  .app-layout .sidebar { padding-top: env(safe-area-inset-top); }
  .settings-nav { top: 64px; }
  .settings-pane { padding: 24px 20px; }
  .dialog-header { padding: 16px 20px; }
}
@media (max-width: 600px) {
  .remote-header {
    height: calc(64px + env(safe-area-inset-top));
    padding-inline: max(14px, env(safe-area-inset-left)) max(14px, env(safe-area-inset-right));
  }
  .remote-speech { border-radius: var(--marvin-radius-panel); }
  .remote-status { border-radius: 50%; }
}
@media (max-width: 900px) and (max-height: 520px) and (orientation: landscape) {
  .remote-header { height: calc(52px + env(safe-area-inset-top)); }
}
EOF
