import { useCallback, useEffect, useLayoutEffect, useReducer, useRef, type MouseEvent } from "react"

import { useMediaQuery } from "@/hooks/useMediaQuery"

import {
  initialSidebarInteraction,
  sidebarInteractionReducer,
  sidebarMode,
} from "./sidebarInteraction"
import { useSidebarExpanded } from "./useSidebarExpanded"

const FLOATING_CONTENT_SELECTOR = "[data-sidebar-floating-content]"
const OPEN_FLOATING_TRIGGER_SELECTOR = '[data-sidebar-floating-trigger][data-state="open"]'
const VIEWPORT_LEAVE_DELAY_MS = 800

function isFloatingContent(target: EventTarget | null) {
  return target instanceof Element && target.closest(FLOATING_CONTENT_SELECTOR) != null
}

function containsFocus(sidebar: HTMLElement | null, target: EventTarget | null) {
  return target instanceof Element && (sidebar?.contains(target) || isFloatingContent(target))
}

function hasOpenDropdown(sidebar: HTMLElement | null) {
  return sidebar?.querySelector(OPEN_FLOATING_TRIGGER_SELECTOR) != null
}

function isPageOverlayActive() {
  const overlays = document.querySelectorAll(
    '[role="dialog"][aria-modal="true"], [data-page-overlay]',
  )
  for (const overlay of overlays) {
    const visible =
      typeof overlay.checkVisibility === "function"
        ? overlay.checkVisibility()
        : overlay.isConnected && getComputedStyle(overlay).display !== "none"
    if (visible) return true
  }
  return false
}

/** Owns transient sidebar gestures, their DOM effects, and interruption cleanup. */
export function useSidebarInteraction() {
  const isDesktop = useMediaQuery("(min-width: 768px)")
  const [isDesktopExpanded, setIsDesktopExpanded] = useSidebarExpanded()
  const environment = { isDesktop, isExpanded: isDesktopExpanded }
  const [storedInteraction, dispatch] = useReducer(
    sidebarInteractionReducer,
    environment,
    initialSidebarInteraction,
  )
  // Reconcile external changes before rendering, including the shared keyboard
  // shortcut and cross-tab preference updates. No frame retains an old gesture.
  const environmentEvent = { type: "environment-changed", environment } as const
  const interaction = sidebarInteractionReducer(storedInteraction, environmentEvent)
  if (interaction !== storedInteraction) dispatch(environmentEvent)
  const mode = sidebarMode(interaction)

  const sidebarRef = useRef<HTMLElement | null>(null)
  const logoRef = useRef<HTMLDivElement | null>(null)
  const mainRef = useRef<HTMLElement | null>(null)
  const viewportLeaveTimeoutRef = useRef<number | null>(null)
  const currentRef = useRef({ mode, isDesktopExpanded })
  useLayoutEffect(() => {
    currentRef.current = { mode, isDesktopExpanded }
  }, [isDesktopExpanded, mode])

  const cancelViewportLeave = useCallback(() => {
    if (viewportLeaveTimeoutRef.current != null) {
      window.clearTimeout(viewportLeaveTimeoutRef.current)
      viewportLeaveTimeoutRef.current = null
    }
  }, [])

  const closeFloating = useCallback(
    (options?: { focusMain?: boolean }) => {
      cancelViewportLeave()
      dispatch({ type: "close-floating" })
      if (options?.focusMain) mainRef.current?.focus({ preventScroll: true })
    },
    [cancelViewportLeave],
  )

  const openDrawer = useCallback(() => {
    cancelViewportLeave()
    dispatch({ type: "open-drawer" })
  }, [cancelViewportLeave])
  const closeDrawer = useCallback(() => dispatch({ type: "close-drawer" }), [])

  const expandDesktop = useCallback(() => {
    closeFloating()
    setIsDesktopExpanded(true)
  }, [closeFloating, setIsDesktopExpanded])
  const collapseDesktop = useCallback(() => {
    closeDrawer()
    closeFloating()
    setIsDesktopExpanded(false)
  }, [closeFloating, closeDrawer, setIsDesktopExpanded])

  useEffect(() => {
    if (mode !== "drawer-open") return
    const originalOverflow = document.body.style.overflow
    document.body.style.overflow = "hidden"
    return () => {
      document.body.style.overflow = originalOverflow
    }
  }, [mode])

  const previousEnvironmentRef = useRef(environment)
  useLayoutEffect(() => {
    cancelViewportLeave()
    const previous = previousEnvironmentRef.current
    const collapsed = previous.isExpanded && !isDesktopExpanded
    const hiddenByViewport = previous.isDesktop && !isDesktop && mode === "mobile-closed"
    if (
      (collapsed || hiddenByViewport) &&
      containsFocus(sidebarRef.current, document.activeElement)
    )
      mainRef.current?.focus({ preventScroll: true })
    previousEnvironmentRef.current = { isDesktop, isExpanded: isDesktopExpanded }
  }, [cancelViewportLeave, isDesktop, isDesktopExpanded, mode])

  useEffect(() => {
    let pointerFocusPending = false
    let pointerFocusFrame: number | null = null
    let focusLeaveTimeout: number | null = null
    let wasFocusWithin = false

    const clearPointerFocus = () => {
      pointerFocusPending = false
      if (pointerFocusFrame != null) cancelAnimationFrame(pointerFocusFrame)
      pointerFocusFrame = null
    }
    const clearFocusLeave = () => {
      if (focusLeaveTimeout != null) window.clearTimeout(focusLeaveTimeout)
      focusLeaveTimeout = null
    }
    const onPointerDown = () => {
      clearPointerFocus()
      pointerFocusPending = true
      pointerFocusFrame = requestAnimationFrame(clearPointerFocus)
    }
    const onFocusIn = (event: FocusEvent) => {
      clearFocusLeave()
      if (!containsFocus(sidebarRef.current, event.target)) {
        clearPointerFocus()
        wasFocusWithin = false
        dispatch({ type: "focus-left" })
        return
      }
      const origin = pointerFocusPending ? "pointer" : "keyboard"
      clearPointerFocus()
      const justEntered = !wasFocusWithin
      wasFocusWithin = true
      const current = currentRef.current
      if (current.isDesktopExpanded || current.mode === "drawer-open" || isPageOverlayActive())
        return
      if (current.mode !== "desktop-floating") {
        window.dispatchEvent(new CustomEvent("sidebar-expand"))
      }
      dispatch({ type: "focus-entered", origin })
      // Keyboard entry starts at the first link in a floating sidebar. Pinned
      // navigation and pointer clicks preserve the user's target and tab order.
      if (justEntered && current.mode === "desktop-floating" && origin === "keyboard") {
        const firstLink = sidebarRef.current?.querySelector<HTMLAnchorElement>(
          'a[href]:not([tabindex="-1"])',
        )
        if (firstLink && event.target !== firstLink) firstLink.focus({ preventScroll: true })
      }
    }
    const onFocusOut = () => {
      clearFocusLeave()
      focusLeaveTimeout = window.setTimeout(() => {
        focusLeaveTimeout = null
        if (!containsFocus(sidebarRef.current, document.activeElement)) {
          wasFocusWithin = false
          dispatch({ type: "focus-left" })
        }
      }, 0)
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Tab" || event.key.startsWith("Arrow")) clearPointerFocus()
      if (event.defaultPrevented || event.key !== "Escape") return
      if (currentRef.current.mode !== "desktop-floating") return
      if (!containsFocus(sidebarRef.current, event.target)) return
      // The first Escape belongs to an open dropdown, including its portal.
      if (isFloatingContent(event.target) || hasOpenDropdown(sidebarRef.current)) return
      event.preventDefault()
      closeFloating({ focusMain: true })
    }

    document.addEventListener("pointerdown", onPointerDown)
    document.addEventListener("focusin", onFocusIn)
    document.addEventListener("focusout", onFocusOut)
    document.addEventListener("keydown", onKeyDown)
    return () => {
      document.removeEventListener("pointerdown", onPointerDown)
      document.removeEventListener("focusin", onFocusIn)
      document.removeEventListener("focusout", onFocusOut)
      document.removeEventListener("keydown", onKeyDown)
      clearPointerFocus()
      clearFocusLeave()
    }
  }, [closeFloating])

  const onMouseEnter = useCallback(() => {
    const current = currentRef.current
    if (current.isDesktopExpanded || current.mode === "drawer-open" || isPageOverlayActive()) return
    cancelViewportLeave()
    if (current.mode !== "desktop-floating") {
      window.dispatchEvent(new CustomEvent("sidebar-expand"))
    }
    dispatch({ type: "pointer-entered" })
  }, [cancelViewportLeave])

  const onMouseLeave = (event: MouseEvent) => {
    if (isDesktopExpanded) return
    const related = event.relatedTarget
    if (
      related instanceof Node &&
      (sidebarRef.current?.contains(related) || logoRef.current?.contains(related))
    )
      return

    cancelViewportLeave()
    const leftViewport =
      event.clientX <= 0 ||
      event.clientY <= 0 ||
      event.clientX >= window.innerWidth ||
      event.clientY >= window.innerHeight
    if (leftViewport) {
      viewportLeaveTimeoutRef.current = window.setTimeout(() => {
        viewportLeaveTimeoutRef.current = null
        dispatch({ type: "pointer-left" })
      }, VIEWPORT_LEAVE_DELAY_MS)
      return
    }
    if (interaction.focus === "pointer" && !hasOpenDropdown(sidebarRef.current)) {
      closeFloating({ focusMain: true })
    } else {
      dispatch({ type: "pointer-left" })
    }
  }

  useEffect(() => {
    if (mode !== "desktop-collapsed") return
    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType !== "mouse" || window.innerWidth < 768) return
      // Full logo width in the header; a narrower edge along the content.
      const threshold = event.clientY <= 52 ? 52 : 24
      if (event.clientX <= threshold) onMouseEnter()
    }
    window.addEventListener("pointermove", onPointerMove)
    return () => window.removeEventListener("pointermove", onPointerMove)
  }, [mode, onMouseEnter])

  useEffect(() => cancelViewportLeave, [cancelViewportLeave])

  return {
    mode,
    isDesktopExpanded,
    sidebarRef,
    logoRef,
    mainRef,
    onMouseEnter,
    onMouseLeave,
    expandDesktop,
    collapseDesktop,
    closeFloating,
    openDrawer,
    closeDrawer,
  }
}
import { useCallback, useEffect } from "react"

import { usePersistentState } from "@/hooks/usePersistentState"

import { sidebarExpandedPreferenceKey, syncSidebarPreference } from "./sidebarPreference"

type SidebarExpandedState = boolean | ((previous: boolean) => boolean)

export function useSidebarExpanded() {
  const [isExpanded, setPersistedExpanded] = usePersistentState(sidebarExpandedPreferenceKey, true)

  useEffect(() => {
    syncSidebarPreference(isExpanded)
  }, [isExpanded])

  const setIsExpanded = useCallback(
    (value: SidebarExpandedState) => {
      setPersistedExpanded((previous) => {
        const next = typeof value === "function" ? value(previous) : value
        syncSidebarPreference(next)
        return next
      })
    },
    [setPersistedExpanded],
  )

  return [isExpanded, setIsExpanded] as const
}
export const sidebarExpandedPreferenceKey = "sidebar-expanded"

export function hydrateSidebarPreference() {
  try {
    const isExpanded = localStorage.getItem("entire:sidebar-expanded") !== "false"
    document.documentElement.dataset.sidebarExpanded = String(isExpanded)
  } catch {}
}

export const sidebarPreferenceHydrationScript = `(${hydrateSidebarPreference.toString()})()`

export function syncSidebarPreference(isExpanded: boolean) {
  if (typeof document === "undefined") return
  document.documentElement.dataset.sidebarExpanded = String(isExpanded)
}
import { ChevronDown, Info } from "lucide-react"
import { useEffect, useMemo, useReducer } from "react"

import { useAuth } from "@/app/auth/useAuth"
import { Button } from "@/components/primitives/Button"
import {
  Dropdown,
  DropdownContent,
  DropdownLink,
  DropdownSeparator,
  DropdownTrigger,
} from "@/components/primitives/Dropdown"
import { SidebarFloatingIcon } from "@/components/primitives/icons/SidebarFloatingIcon"
import { SidebarInlineIcon } from "@/components/primitives/icons/SidebarInlineIcon"
import { useRepoPreferencesMigration } from "@/data/preferences/repositories/useRepoPreferencesMigration"
import { useRepoPreferencesQuery } from "@/data/preferences/repositories/useRepoPreferencesQuery"
import {
  prefetchSystemStatus,
  SYSTEM_STATUS_PAGE_URL,
  SYSTEM_STATUS_PRESENTATION,
  useSystemStatus,
} from "@/lib/systemStatus"

import { SidebarSectionSeparator } from "./components/SidebarSection"
import { useSidebarContext, type SidebarContext } from "./context/useSidebarContext"
import { Favorites } from "./Favorites"
import { GlobalNavigation, useGlobalNavItems } from "./GlobalNavigation"
import { OrganizationSidebar } from "./organization/OrganizationSidebar"
import { ProjectSidebar } from "./project/ProjectSidebar"
