import { useRepositoryPinning } from "./repository/useRepositoryPinning"

function SidebarToggleIcon({ showInline }: { showInline: boolean }) {
  return (
    <span className="relative flex size-4.5 items-center justify-center">
      <SidebarInlineIcon
        className={`absolute transition-all duration-150 ease-out ${
          showInline
            ? "scale-100 opacity-100 group-hover:scale-90 group-hover:opacity-0 group-focus:scale-90 group-focus:opacity-0"
            : "scale-90 opacity-0 group-hover:scale-100 group-hover:opacity-100 group-focus:scale-100 group-focus:opacity-100"
        }`}
      />
      <SidebarFloatingIcon
        className={`absolute transition-all duration-150 ease-out ${
          showInline
            ? "scale-90 opacity-0 group-hover:scale-100 group-hover:opacity-100 group-focus:scale-100 group-focus:opacity-100"
            : "scale-100 opacity-100 group-hover:scale-90 group-hover:opacity-0 group-focus:scale-90 group-focus:opacity-0"
        }`}
      />
    </span>
  )
}

interface SidebarProps {
  isDesktopExpanded: boolean
  isFloating: boolean
  isDrawerOpen: boolean
  onCollapseDesktop: () => void
  onExpandDesktop: () => void
  onCloseFloat: (options?: { focusMain?: boolean }) => void
  onCloseDrawer: () => void
}

export function Sidebar({
  isDesktopExpanded,
  isFloating,
  isDrawerOpen,
  onCollapseDesktop,
  onExpandDesktop,
  onCloseFloat,
  onCloseDrawer,
}: SidebarProps) {
  const handleNavigate = () => {
    if (isDrawerOpen) {
      onCloseDrawer()
    } else if (isFloating) {
      onCloseFloat({ focusMain: true })
    }
  }

  return (
    <div className="relative grid h-full max-h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)_auto] overflow-hidden bg-base">
      <SidebarHeader
        isDesktopExpanded={isDesktopExpanded}
        isFloating={isFloating}
        isDrawerOpen={isDrawerOpen}
        onCollapseDesktop={onCollapseDesktop}
        onExpandDesktop={onExpandDesktop}
        onCloseDrawer={onCloseDrawer}
      />

      <SidebarNavigation onNavigate={handleNavigate} />

      <SidebarFooter />
    </div>
  )
}

const aboutSubItems = [
  { to: "/about", label: "About" },
  { to: "/blog?category=Changelog", label: "Changelog" },
  { to: "https://docs.entire.io/", label: "Documentation" },
]

function SidebarStatusLink({ status }: { status: ReturnType<typeof useSystemStatus> }) {
  const presentation = status
    ? SYSTEM_STATUS_PRESENTATION[status]
    : { dotClassName: "bg-neutral-400", label: "Status page" }

  return (
    <DropdownLink href={SYSTEM_STATUS_PAGE_URL} target="_blank" rel="noopener noreferrer">
      <span className="flex items-center gap-2 text-xs text-muted">
        <span className={`size-1.75 shrink-0 rounded-full ${presentation.dotClassName}`} />
        {presentation.label}
      </span>
    </DropdownLink>
  )
}

function SidebarFooter() {
  const status = useSystemStatus()

  useEffect(() => {
    void prefetchSystemStatus()
  }, [])

  return (
    <div data-testid="sidebar-footer" className="border-t border-subtle py-2">
      <Dropdown>
        <DropdownTrigger asChild>
          <button
            type="button"
            className="group relative isolate flex h-9 w-full min-w-0 cursor-pointer items-center gap-0.5 px-2 text-sm list-hover-transition before:absolute before:inset-x-2 before:inset-y-0 before:-z-10 before:rounded-lg before:outline-2 before:-outline-offset-2 before:outline-transparent hover:before:bg-hover focus-visible:outline-0 focus-visible:before:outline-focus"
            data-sidebar-floating-trigger
            onMouseEnter={() => void prefetchSystemStatus()}
            onPointerDown={() => void prefetchSystemStatus()}
            onFocus={() => void prefetchSystemStatus()}
          >
            <span className="flex size-9 shrink-0 items-center justify-center">
              <Info size={16} className="shrink-0 text-muted transition-transform duration-300" />
            </span>
            <span className="min-w-0 flex-1 truncate text-left text-default">Info</span>
            <ChevronDown
              size={16}
              className="mr-2 shrink-0 text-muted transition-transform duration-200 group-data-[state=open]:rotate-180"
            />
          </button>
        </DropdownTrigger>
        <DropdownContent data-sidebar-floating-content>
          {aboutSubItems.map((item) => (
            <DropdownLink key={item.to} href={item.to}>
              {item.label}
            </DropdownLink>
          ))}
          <DropdownSeparator />
          <SidebarStatusLink status={status} />
        </DropdownContent>
      </Dropdown>
    </div>
  )
}

interface SidebarHeaderProps {
  isDesktopExpanded: boolean
  isFloating: boolean
  isDrawerOpen: boolean
  onCollapseDesktop: () => void
  onExpandDesktop: () => void
  onCloseDrawer: () => void
