import { useMemo, useState, type ReactNode } from "react"

import { useAuth } from "@/app/auth/useAuth"
import { GettingStartedContext } from "@/app/getting-started/useGettingStarted"
import { MarvinLogoLink } from "@/app/marvin/MarvinLogoLink"
import { Sidebar } from "@/app/sidebar/Sidebar"
import { useRepoNavState } from "@/app/sidebar/useRepoNavState"
