import { useFilterTabsMigration } from "@/data/preferences/filter-tabs/useFilterTabsMigration"
import { useCoarsePointer } from "@/hooks/useCoarsePointer"
import { useRepositoryNavigation } from "@/lib/repositories/useRepositoryNavigation"

import { AppHeader } from "./AppHeader"
import { AppLayoutContext, SidebarDrawerContext } from "./useSidebarDrawer"

interface AppLayoutProps {
  children: ReactNode
}

export function AppLayout({ children }: AppLayoutProps) {
  const { isAuthenticated } = useAuth()
  const { routeRepoFullName } = useRepoNavState()

  useFilterTabsMigration(isAuthenticated)

  const isCoarsePointer = useCoarsePointer()

  const interaction = useSidebarInteraction()
  const { isDesktopExpanded, sidebarRef, logoRef, mainRef } = interaction
  const isFloating = interaction.mode === "desktop-floating"
  const isDrawerOpen = interaction.mode === "drawer-open"
  const { isPublicRepo, homeHref } = useRepositoryNavigation(routeRepoFullName)

  const sidebarClasses = [
    "transition-transform duration-150 ease-out",
    "overflow-hidden fixed inset-y-0 start-0 z-overlay w-68",
    isFloating || isDrawerOpen
      ? "translate-x-0"
      : "-translate-x-full md:translate-x-0 sidebar-collapsed:md:-translate-x-full",
    isFloating
      ? "md:border-r md:border-subtle md:shadow-lg"
      : "md:border-r md:border-subtle sidebar-collapsed:md:border-r-0",
    isDrawerOpen ? "shadow-lg" : "",
  ].join(" ")

  const headerClassName =
    "transition-[left] duration-150 ease-out md:left-68 sidebar-collapsed:md:left-13"

  const [gettingStartedOpen, setGettingStartedOpen] = useState(false)
  const gettingStartedContextValue = useMemo(
    () => ({ isOpen: gettingStartedOpen, setOpen: setGettingStartedOpen }),
    [gettingStartedOpen],
  )

  const sidebarDrawerContextValue = useMemo(
    () => ({
      openDrawer: interaction.openDrawer,
    }),
    [interaction.openDrawer],
  )

  return (
    <AppLayoutContext.Provider value={true}>
      <SidebarDrawerContext.Provider value={sidebarDrawerContextValue}>
        <GettingStartedContext.Provider value={gettingStartedContextValue}>
          {/* Persistent logo — the first focusable element on the page.
            Rendered before the sidebar so it leads the tab order, and painted
            above the sidebar (z higher than overlay) so it stays visible when
            the sidebar floats in under it. */}
          <div
            ref={logoRef}
            className={`fixed top-0 left-0 z-55 h-(--global-header-height) w-13 items-center justify-center border-b border-subtle bg-base px-2 ${
              isDrawerOpen ? "flex" : "hidden md:flex"
            }`}
            onMouseEnter={interaction.onMouseEnter}
            onMouseLeave={interaction.onMouseLeave}
          >
            <MarvinLogoLink
              to={homeHref}
              external={isPublicRepo}
              onClick={interaction.closeDrawer}
            />
          </div>

          {/* oxlint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- hover opens the sidebar; focus handlers provide keyboard parity */}
          <aside
            ref={sidebarRef}
            className={sidebarClasses}
            role="dialog"
            aria-label="Sidebar"
            onMouseEnter={interaction.onMouseEnter}
            onMouseLeave={interaction.onMouseLeave}
          >
            <Sidebar
              isDesktopExpanded={isDesktopExpanded}
              isFloating={isFloating}
              isDrawerOpen={isDrawerOpen}
              onCollapseDesktop={interaction.collapseDesktop}
              onExpandDesktop={interaction.expandDesktop}
              onCloseFloat={interaction.closeFloating}
              onCloseDrawer={interaction.closeDrawer}
            />
          </aside>

          <div
            className={`fixed inset-0 z-backdrop bg-neutral-900/60 backdrop-blur-sm transition-opacity duration-150 ${
              isCoarsePointer ? "" : "md:hidden"
            } ${isDrawerOpen ? "opacity-100" : "pointer-events-none opacity-0"}`}
            onClick={interaction.closeDrawer}
          />

          <main
            ref={mainRef}
            tabIndex={-1}
            className="flex min-h-dvh min-w-0 flex-col transition-[margin] duration-150 ease-out focus:outline-none md:ml-68 sidebar-collapsed:md:ml-0"
          >
            <div className="flex min-h-0 min-w-0 flex-1 flex-col">
              <AppHeader headerClassName={headerClassName} />
              <div className="min-w-0 flex-1">
                {/* No horizontal-overflow clip here: it's an ancestor of sticky
                  sidebars on detail pages and would make WebKit jitter. */}
                <div className="isolate flex min-h-[calc(100dvh-var(--global-header-height))] min-w-0 flex-col bg-base">
                  {children}
                </div>
              </div>
            </div>
          </main>
        </GettingStartedContext.Provider>
      </SidebarDrawerContext.Provider>
    </AppLayoutContext.Provider>
  )
}
import { Link, type ResolveParams } from "@tanstack/react-router"
import type { ReactNode } from "react"

import { Badge } from "@/components/primitives/Badge"
import type { FileRouteTypes } from "@/routeTree.gen"

/** Every sidebar row: 36px tall, icon cell first, content truncates. */
export const sidebarRowLayoutClassName = "flex h-9 min-w-0 items-center gap-0.5 px-2 text-sm"
export const sidebarLinkClassName =
  "list-hover-transition group relative isolate flex h-9 w-full items-center gap-0.5 px-2 text-sm focus-visible:outline-0 before:absolute before:inset-y-0 before:inset-x-2 before:rounded-lg before:-z-10 hover:before:bg-hover before:outline-2 before:-outline-offset-2 before:outline-transparent focus-visible:before:outline-focus"
const sidebarActiveLinkClassName =
  "list-hover-transition group relative isolate flex h-9 w-full items-center gap-0.5 px-2 text-sm focus-visible:outline-0 before:absolute before:inset-y-0 before:inset-x-2 before:rounded-lg before:-z-10 before:bg-selected before:outline-2 before:-outline-offset-2 before:outline-transparent focus-visible:before:outline-focus"
export const sidebarRowClassName =
  "list-hover-transition relative isolate flex h-9 w-full items-center gap-0.5 px-2 text-sm focus-visible:outline-0 before:absolute before:inset-y-0 before:inset-x-2 before:rounded-lg before:-z-10 hover:before:bg-hover before:outline-2 before:-outline-offset-2 before:outline-transparent focus-visible:before:outline-focus"

type SidebarRouteTo = FileRouteTypes["to"]

/** A destination and its required path parameters stay paired at every call site. */
export type SidebarDestination = {
  [TTo in SidebarRouteTo]: { to: TTo } & (keyof ResolveParams<TTo> extends never
    ? { params?: never }
    : { params: ResolveParams<TTo> })
}[SidebarRouteTo]

export type SidebarStaticRouteTo = Extract<SidebarDestination, { params?: never }>["to"]

export function SidebarNavList({ children }: { children: ReactNode }) {
  return <ul className="flex min-w-0 flex-col gap-px [&>li]:min-w-0">{children}</ul>
}

export function SidebarIconSlot({ children }: { children: ReactNode }) {
  return <span className="flex size-9 shrink-0 items-center justify-center">{children}</span>
}

function SidebarLinkBody({
  icon,
  label,
  isActive,
  preview,
}: {
  icon: ReactNode
  label: string
  isActive: boolean
  preview?: boolean
}) {
  return (
    <>
      <SidebarIconSlot>{icon}</SidebarIconSlot>
      <span
        className={`min-w-0 truncate text-default ${isActive ? "font-semibold" : "font-normal"}`}
      >
        {label}
      </span>
      {preview && <Badge className="mr-2 ml-auto">Preview</Badge>}
    </>
  )
}

/**
 * A sidebar navigation row. `active` says who owns the highlight: `"route"`
 * lets the Router light the link up when the location matches; a boolean is
 * derived by the caller, which repository menus use so the committed selection
 * stays highlighted while the next target is still pending.
 */
export function SidebarNavLink({
  to,
  params,
  icon,
  label,
  active,
  preview,
  onClick,
}: SidebarDestination & {
  icon: ReactNode
  label: string
  active: "route" | boolean
  preview?: boolean
  onClick?: () => void
}) {
  if (active === "route") {
    return (
      <li>
        <Link
          to={to}
          params={params}
          className={`${sidebarLinkClassName} min-w-0`}
          activeProps={{ className: `${sidebarActiveLinkClassName} min-w-0` }}
          onClick={onClick}
        >
          {({ isActive }) => (
            <SidebarLinkBody icon={icon} label={label} isActive={isActive} preview={preview} />
          )}
        </Link>
      </li>
    )
  }

  return (
    <li>
      <Link
        to={to}
        params={params}
        className={`${active ? sidebarActiveLinkClassName : sidebarLinkClassName} min-w-0`}
        onClick={onClick}
      >
        {() => <SidebarLinkBody icon={icon} label={label} isActive={active} preview={preview} />}
      </Link>
    </li>
  )
}

/** A link inside a collapsible group: indented, without an icon cell. */
export function SidebarNestedLink({
  to,
  params,
  label,
  isActive = false,
  onClick,
  trailing,
}: SidebarDestination & {
  label: string
  isActive?: boolean
  onClick?: () => void
  trailing?: ReactNode
}) {
  return (
    <li className="relative">
      <Link
        to={to}
        params={params}
        className={`group flex h-9 w-full min-w-0 items-center rounded-lg px-3 text-sm list-hover-transition focus-visible:outline-2 focus-visible:outline-focus ${
          isActive ? "bg-selected font-semibold text-default" : "text-default hover:bg-hover"
        }`}
        onClick={onClick}
      >
import { createContext, useContext } from "react"

interface SidebarDrawerContextValue {
  openDrawer: () => void
}

export const AppLayoutContext = createContext(false)

export const SidebarDrawerContext = createContext<SidebarDrawerContextValue | null>(null)

export function useSidebarDrawer() {
  const context = useContext(SidebarDrawerContext)
  if (!context) {
    throw new Error("useSidebarDrawer must be used within AppLayout")
  }
  return context
}

export function useInAppLayout() {
  return useContext(AppLayoutContext)
