import { AppHeader } from "./AppHeader"
import { AppLayoutContext, SidebarDrawerContext } from "./useSidebarDrawer"

interface AppLayoutProps {
  children: ReactNode
}

export function AppLayout({ children }: AppLayoutProps) {
  const { isAuthenticated } = useAuth()
  const { routeRepoFullName } = useRepoNavState()

  useFilterTabsMigration(isAuthenticated)

  const isCoarsePointer = useCoarsePointer()

  const interaction = useSidebarInteraction()
  const { isDesktopExpanded, sidebarRef, logoRef, mainRef } = interaction
  const isFloating = interaction.mode === "desktop-floating"
  const isDrawerOpen = interaction.mode === "drawer-open"
  const { isPublicRepo, homeHref } = useRepositoryNavigation(routeRepoFullName)

  const sidebarClasses = [
    "transition-transform duration-150 ease-out",
    "overflow-hidden fixed inset-y-0 start-0 z-overlay w-68",
    isFloating || isDrawerOpen
      ? "translate-x-0"
      : "-translate-x-full md:translate-x-0 sidebar-collapsed:md:-translate-x-full",
    isFloating
      ? "md:border-r md:border-subtle md:shadow-lg"
      : "md:border-r md:border-subtle sidebar-collapsed:md:border-r-0",
    isDrawerOpen ? "shadow-lg" : "",
  ].join(" ")

  const headerClassName =
    "transition-[left] duration-150 ease-out md:left-68 sidebar-collapsed:md:left-13"

  const [gettingStartedOpen, setGettingStartedOpen] = useState(false)
  const gettingStartedContextValue = useMemo(
    () => ({ isOpen: gettingStartedOpen, setOpen: setGettingStartedOpen }),
    [gettingStartedOpen],
  )

  const sidebarDrawerContextValue = useMemo(
    () => ({
      openDrawer: interaction.openDrawer,
    }),
    [interaction.openDrawer],
  )

  return (
    <AppLayoutContext.Provider value={true}>
      <SidebarDrawerContext.Provider value={sidebarDrawerContextValue}>
        <GettingStartedContext.Provider value={gettingStartedContextValue}>
          {/* Persistent logo — the first focusable element on the page.
            Rendered before the sidebar so it leads the tab order, and painted
            above the sidebar (z higher than overlay) so it stays visible when
            the sidebar floats in under it. */}
          <div
            ref={logoRef}
            className={`fixed top-0 left-0 z-55 h-(--global-header-height) w-13 items-center justify-center border-b border-subtle bg-base px-2 ${
              isDrawerOpen ? "flex" : "hidden md:flex"
            }`}
            onMouseEnter={interaction.onMouseEnter}
            onMouseLeave={interaction.onMouseLeave}
          >
            <MarvinLogoLink
              to={homeHref}
              external={isPublicRepo}
              onClick={interaction.closeDrawer}
            />
          </div>

          {/* oxlint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- hover opens the sidebar; focus handlers provide keyboard parity */}
          <aside
            ref={sidebarRef}
            className={sidebarClasses}
            role="dialog"
            aria-label="Sidebar"
            onMouseEnter={interaction.onMouseEnter}
            onMouseLeave={interaction.onMouseLeave}
          >
            <Sidebar
              isDesktopExpanded={isDesktopExpanded}
              isFloating={isFloating}
              isDrawerOpen={isDrawerOpen}
              onCollapseDesktop={interaction.collapseDesktop}
              onExpandDesktop={interaction.expandDesktop}
              onCloseFloat={interaction.closeFloating}
              onCloseDrawer={interaction.closeDrawer}
            />
          </aside>

          <div
            className={`fixed inset-0 z-backdrop bg-neutral-900/60 backdrop-blur-sm transition-opacity duration-150 ${
              isCoarsePointer ? "" : "md:hidden"
            } ${isDrawerOpen ? "opacity-100" : "pointer-events-none opacity-0"}`}
            onClick={interaction.closeDrawer}
          />

          <main
            ref={mainRef}
            tabIndex={-1}
            className="flex min-h-dvh min-w-0 flex-col transition-[margin] duration-150 ease-out focus:outline-none md:ml-68 sidebar-collapsed:md:ml-0"
          >
            <div className="flex min-h-0 min-w-0 flex-1 flex-col">
              <AppHeader headerClassName={headerClassName} />
              <div className="min-w-0 flex-1">
                {/* No horizontal-overflow clip here: it's an ancestor of sticky
                  sidebars on detail pages and would make WebKit jitter. */}
                <div className="isolate flex min-h-[calc(100dvh-var(--global-header-height))] min-w-0 flex-col bg-base">
                  {children}
                </div>
              </div>
            </div>
          </main>
        </GettingStartedContext.Provider>
      </SidebarDrawerContext.Provider>
    </AppLayoutContext.Provider>
  )
}
