        <button className="sidebar-row" onClick={() => { nav.navigate(); onSettings(); }}>
          <span className="sidebar-icon"><Settings size={16}/></span><span>Settings</span>
        </button>
        <details className="sidebar-account">
          <summary className="sidebar-row"><span className="sidebar-icon"><span className="sidebar-avatar">{ownerName[0]}</span></span><span>{ownerName}</span><ChevronDown className="sidebar-trailing" size={14}/></summary>
          <div className="sidebar-account-menu">
            <p>{development ? 'Local preview' : 'Personal workspace'}</p>
            <button className="sidebar-row" onClick={() => { nav.navigate(); onLogout(); }}><span className="sidebar-icon"><LogOut size={16}/></span><span>Sign out</span></button>
          </div>
        </details>
      </footer>
    </aside>
  </>;
}
