import { useNavigate } from "@tanstack/react-router"
import { useState } from "react"

import { resolveDisplayName } from "@/app/auth/currentAuthState"
import { useAuth } from "@/app/auth/useAuth"
import { useGitHubInstallationUrl } from "@/app/auth/useGitHubInstallationUrl"
import { SupportDialog } from "@/app/support/SupportDialog"
import {
  GitHubAvatar,
  Dropdown,
  DropdownTrigger,
  DropdownContent,
  DropdownItem,
  DropdownLink,
  DropdownSeparator,
  DropdownSub,
  DropdownSubTrigger,
  DropdownSubContent,
  DropdownSubItem,
} from "@/components"
import { useOrganizationProjectManagementFeatureFlag } from "@/lib/featureFlags"
import { useTheme } from "@/lib/theme"

export function HeaderAccountMenu() {
  const { user, logout } = useAuth()
  const { mode, setMode } = useTheme()
  const navigate = useNavigate()
  const [supportOpen, setSupportOpen] = useState(false)
  const isManagementEnabled = useOrganizationProjectManagementFeatureFlag()

  const displayName = resolveDisplayName(user) || (user ? "Account" : "Guest")
  const avatarInitial = displayName.charAt(0).toUpperCase()
  const installationUrl = useGitHubInstallationUrl()

  const themeOptions = [
    { value: "light" as const, label: "Light" },
    { value: "dark" as const, label: "Dark" },
    { value: "auto" as const, label: "Auto" },
  ]

  return (
    <Dropdown>
      <DropdownTrigger asChild>
        <button
          className="flex size-10 items-center justify-center rounded-full transition-colors hover:bg-hover focus:bg-hover focus:outline-2 focus:-outline-offset-2 focus:outline-transparent focus:transition-none focus-visible:outline-focus"
          aria-label="Account menu"
        >
          <GitHubAvatar
            username={user?.github_login ?? undefined}
            fallbackInitial={avatarInitial}
            className="size-8"
          />
        </button>
      </DropdownTrigger>
      <DropdownContent align="end">
        {user && (
          <>
            <DropdownLink
              href="/account"
              onClick={(e) => {
                if (!e.metaKey && !e.ctrlKey && !e.shiftKey && e.button === 0) {
                  e.preventDefault()
                  navigate({ to: "/account" })
                }
              }}
            >
              Account settings
            </DropdownLink>
            {isManagementEnabled ? (
              <DropdownLink
                href="/organizations"
                onClick={(event) => {
                  if (!event.metaKey && !event.ctrlKey && !event.shiftKey && event.button === 0) {
                    event.preventDefault()
                    navigate({ to: "/organizations" })
                  }
                }}
              >
                Organizations
              </DropdownLink>
            ) : null}
            {installationUrl !== null ? (
              <DropdownItem onClick={() => window.open(installationUrl, "_blank")}>
                Configure access
              </DropdownItem>
            ) : null}
            <DropdownSeparator />
          </>
        )}
        <DropdownSub>
          <DropdownSubTrigger>Theme</DropdownSubTrigger>
          <DropdownSubContent>
            {themeOptions.map((option) => (
              <DropdownSubItem
                key={option.value}
                onClick={() => setMode(option.value)}
                selected={mode === option.value}
              >
                {option.label}
              </DropdownSubItem>
            ))}
          </DropdownSubContent>
        </DropdownSub>
        {user && (
          <>
            <DropdownSeparator />
            <DropdownItem onClick={() => setSupportOpen(true)}>Contact support</DropdownItem>
            <DropdownItem onClick={() => void logout()}>Logout</DropdownItem>
          </>
        )}
      </DropdownContent>
      {user && <SupportDialog open={supportOpen} onOpenChange={setSupportOpen} />}
    </Dropdown>
  )
}
