function repositoryComboboxOption(option: RepositoryOption): ComboboxOption {
  const isGitHub = option.reference.forge === "gh"

  return {
    id: repositoryOptionId(option),
    label: option.label,
    displayLabel: (
      <span className="flex min-w-0 flex-1 items-center gap-2">
