function SidebarSelectorOptions() {
  const { filteredOptions } = useCombobox()
  return filteredOptions.map((option, index) => (
    <ComboboxItem key={option.id} option={option} index={index}>
      {option.displayLabel != null ? (
        <>
          <span className="sr-only">{option.label}</span>
          <span aria-hidden="true" className="flex min-w-0 flex-1">
            {option.displayLabel}
          </span>
        </>
      ) : (
        <MiddleTruncatedText text={option.label} tooltip={false} />
      )}
    </ComboboxItem>
  ))
}

/** Shared picker interaction and geometry. Entity controllers own data and navigation. */
export function SidebarSelector({
  label,
  selectedId,
  options,
  source,
  onSelect,
  searchPlaceholder,
  emptyMessage,
  children,
  actions,
}: {
  label: string
  selectedId: string | undefined
  options: ComboboxOption[]
  source: AsyncComboboxSource
  onSelect: (id: string) => void
  searchPlaceholder: string
  emptyMessage: string
  children: ReactNode
  actions?: ReactNode
}) {
  const [isOpen, setIsOpen] = useState(false)
  const chevronRef = useRef<HTMLButtonElement | null>(null)

  return (
    <ul className="mb-px flex min-w-0 flex-col gap-px">
      <li className="group relative isolate flex h-9 min-w-0 items-center px-2 list-hover-transition before:absolute before:inset-x-2 before:inset-y-0 before:-z-10 before:rounded-lg before:outline-2 before:-outline-offset-2 before:outline-transparent hover:before:bg-hover">
        <Combobox
          options={options}
          async={source}
          value={selectedId ? [selectedId] : []}
          open={isOpen}
          onOpenChange={setIsOpen}
          additionalTriggerRefs={[chevronRef]}
          onChange={(selected) => {
            if (selected[0]) onSelect(selected[0])
          }}
        >
          <ComboboxTrigger asChild>
            <button
              type="button"
              data-sidebar-floating-trigger
              className="peer relative flex h-9 min-w-0 flex-1 cursor-pointer items-center gap-0.5 rounded-lg text-sm outline-2 -outline-offset-2 outline-transparent focus-visible:outline-focus"
              aria-label={`Switch ${label}`}
              aria-current={selectedId ? "page" : undefined}
            >
              {children}
            </button>
          </ComboboxTrigger>
          <ComboboxContent data-sidebar-floating-content>
            <ComboboxInput placeholder={searchPlaceholder} />
            <ComboboxList emptyMessage={emptyMessage}>
              <SidebarSelectorOptions />
            </ComboboxList>
          </ComboboxContent>
        </Combobox>
        {actions}
        <button
          ref={chevronRef}
          type="button"
          className="relative z-10 mr-1 flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-lg text-muted list-hover-transition hover:bg-hover focus-visible:outline-2 focus-visible:outline-focus"
          aria-label={`${isOpen ? "Close" : "Open"} ${label} selector`}
          aria-haspopup="listbox"
          aria-expanded={isOpen}
          onClick={() => setIsOpen((open) => !open)}
        >
          <ChevronsUpDown size={16} strokeWidth={1.5} aria-hidden="true" />
        </button>
      </li>
    </ul>
  )
}

const switchTransition = { duration: 0.26, ease: [0.32, 0.72, 0, 1] as const }
const switchInitial = { opacity: 0, x: 12, filter: "blur(4px)" }
const switchAnimate = { opacity: 1, x: 0, filter: "blur(0px)" }
const switchExit = { opacity: 0, x: -12, filter: "blur(4px)" }
const reducedExit = { opacity: 0 }
const reducedTransition = { duration: 0.12 }

/** Composable animated identity, including the repository's unselected placeholder. */
export function SidebarSelectorIdentity({
  identityKey,
  icon,
  children,
}: {
  identityKey: string
  icon: ReactNode
  children: ReactNode
}) {
  const prefersReducedMotion = useReducedMotion()
  return (
    <AnimatePresence initial={false} mode="popLayout">
      <motion.span
        key={identityKey}
        className="flex min-w-0 flex-1 items-center gap-0.5"
        initial={prefersReducedMotion ? false : switchInitial}
        animate={switchAnimate}
        exit={prefersReducedMotion ? reducedExit : switchExit}
        transition={prefersReducedMotion ? reducedTransition : switchTransition}
      >
        <SidebarIconSlot>{icon}</SidebarIconSlot>
        {children}
      </motion.span>
    </AnimatePresence>
  )
}

export function SidebarSelectorName({ children }: { children: string }) {
  return (
    <span className="min-w-0 flex-1 scroll-fade-r overflow-hidden text-left font-semibold whitespace-nowrap text-default [--scroll-fade-reveal:1px] scroll-fade-6">
      {children}
    </span>
  )
}
