/**
 * The repository switcher. It owns opening, search, pagination, and retry, and
 * starts loading the registry as soon as it mounts so the popup never waits on
 * exact metadata. The trigger keeps its geometry while the current identity
 * changes, resolves, or is missing.
 */
export function RepositorySelector({
  current,
  currentRepoId,
  target,
  recentPreferences,
  pinning,
  onNavigate,
}: {
  /** The repository shown on the trigger; null renders the "select" placeholder. */
  current: RepositoryIdentity | null
  currentRepoId?: string
  /** Section (and Settings subpage) switching keeps on the next repository. */
  target: RepositoryNavigationTarget
  recentPreferences: readonly RepoPreferenceItem[]
  pinning: RepositoryPinning
  onNavigate?: () => void
}) {
  const navigate = useNavigate()
  const [searchQuery, setSearchQuery] = useState("")
  const registryQuery = useRepoRegistryList({ q: searchQuery })

  const options = useMemo(
    () =>
      registryRepositoryOptions({
        registryEntries: registryQuery.data,
        currentReference: current?.reference ?? null,
        currentRepoId,
        targetSection: target.section,
        targetSettingsSubpage: target.settingsSubpage,
        recentPreferences,
        isSearching: searchQuery.trim().length > 0,
      }),
    [current?.reference, currentRepoId, recentPreferences, registryQuery.data, searchQuery, target],
  )
  const currentOption = useMemo(() => {
    if (!current) return undefined
    const key = repositoryReferenceKey(current.reference)
    return options.find((option) => repositoryReferenceKey(option.reference) === key)
  }, [current, options])
  const comboboxOptions = useMemo<ComboboxOption[]>(
    () => (registryQuery.data ? options.map(repositoryComboboxOption) : []),
    [options, registryQuery.data],
  )
  const source = sidebarSelectorSource(registryQuery, {
    query: searchQuery,
    onQueryChange: setSearchQuery,
  })

  const currentNameParts = current ? parseRepositoryFullName(current.fullName) : null
  const canPinCurrent =
    currentOption != null && !pinning.isPinned(currentOption) && pinning.canTogglePin(currentOption)

  const navigateToRepository = (option: RepositoryOption) => {
    void navigate(option.route)
    onNavigate?.()
  }

  return (
    <>
      {pinning.limitReached && (
        <p role="alert" className="mx-5 py-1 text-xs text-red-700 dark:text-red-400">
          You&rsquo;ve reached the pinned repository limit. Unpin another repository to pin this
          one.
        </p>
      )}
      <SidebarSelector
        label="repository"
        selectedId={currentOption ? repositoryOptionId(currentOption) : undefined}
        options={comboboxOptions}
        source={source}
        searchPlaceholder="Find repositories"
        emptyMessage="No repositories found"
        onSelect={(id) => {
          const option = options.find((option) => repositoryOptionId(option) === id)
          if (option) navigateToRepository(option)
        }}
        actions={
          <>
            {current && (
              <span className={providerClassName}>
                <ForgeAvatar
                  forge={current.reference.forge === "gh" ? "github" : "entire"}
                  label={
                    current.reference.forge === "gh"
                      ? "GitHub repository"
                      : "Entire native repository"
                  }
                  variant="inline"
                  className="bg-transparent"
                  iconClassName="text-muted"
                />
              </span>
            )}
            {canPinCurrent && currentOption && (
              <button
                type="button"
                className={pinButtonClassName}
                aria-label={`Pin ${currentOption.label}`}
                disabled={pinning.isPending}
                onClick={() => pinning.pin(currentOption)}
              >
                <Heart
                  size={14}
                  strokeWidth={1.75}
                  fill="none"
                  className="text-muted"
                  aria-hidden="true"
                />
              </button>
            )}
          </>
        }
      >
        <SidebarSelectorIdentity
          identityKey={current ? repositoryReferenceKey(current.reference) : "__no-repo__"}
          icon={
            current ? (
              <RepositoryIdentityIcon reference={current.reference} />
            ) : (
              <span
                data-testid="all-repositories-avatar"
                className="size-5 rounded-[5px] border border-dashed border-default"
                aria-hidden="true"
              />
            )
