import { useAuth } from "@/app/auth/useAuth"
import { GettingStartedHeaderControl } from "@/app/getting-started/GettingStartedHeaderControl"
import { Button } from "@/components/primitives/Button"
import { SidebarFloatingIcon } from "@/components/primitives/icons/SidebarFloatingIcon"
import { RouteBreadcrumbs } from "@/components/RouteBreadcrumbs"
import { useCoarsePointer } from "@/hooks/useCoarsePointer"

import { HeaderAccountMenu } from "./HeaderAccountMenu"
import { useSidebarDrawer } from "./useSidebarDrawer"

export function AppHeader({ headerClassName = "" }: { headerClassName?: string }) {
  const { openDrawer } = useSidebarDrawer()
  const isCoarsePointer = useCoarsePointer()
  const { user, login } = useAuth()

  return (
    <>
      <div className={`fixed inset-x-0 top-0 z-sticky bg-base ${headerClassName}`}>
        <div className="flex h-(--global-header-height) items-center justify-between gap-2 border-b border-subtle pr-2 pl-4 md:pl-6">
          <div className="flex min-w-0 items-center gap-2">
            <div className={isCoarsePointer ? "" : "md:hidden"}>
              <Button variant="outline" size="icon" onClick={openDrawer} aria-label="Open menu">
                <SidebarFloatingIcon />
              </Button>
            </div>
            <RouteBreadcrumbs />
          </div>
          <div className="flex shrink-0 items-center gap-2">
            {user ? <GettingStartedHeaderControl /> : null}
            {user ? <HeaderAccountMenu /> : null}
            {!user ? (
              <Button size="small" onClick={() => login()}>
                Log in
              </Button>
            ) : null}
          </div>
        </div>
      </div>
      <div aria-hidden className="h-(--global-header-height)" />
    </>
  )
}
