import {
  interpolatePath,
  replaceEqualDeep,
  useRouterState,
  type ResolveParams,
} from "@tanstack/react-router"
import { useCallback, useRef, type ComponentType, type ReactElement, type ReactNode } from "react"

import { Breadcrumbs } from "@/components/primitives/Breadcrumbs"
import type { FileRouteTypes } from "@/routeTree.gen"

type RouteRetargetPath = FileRouteTypes["to"]
type RouteTargetPath = string
type RegisteredRouteId = FileRouteTypes["id"]
type RouteParams<TRouteId extends string> = string extends TRouteId
  ? Record<string, string | undefined>
  : ResolveParams<TRouteId>

export interface RouteBreadcrumbMatchSnapshot<
  TRouteId extends string = string,
  TLoaderData = unknown,
> {
  routeId: TRouteId
  fullPath: string
  pathname: string
  params: Readonly<RouteParams<TRouteId>>
  loaderData: TLoaderData | undefined
  retargetTo: RouteRetargetPath | undefined
}

export interface RouteBreadcrumbProps<TRouteId extends string = string, TLoaderData = never> {
  match: RouteBreadcrumbMatchSnapshot<TRouteId, TLoaderData>
  children: (content: ReactNode | RouteBreadcrumbItem[] | null) => ReactNode
}

export interface RouteBreadcrumbItem {
  content: ReactNode
  link?: boolean
  retargetTo?: RouteRetargetPath
}

export type RouteBreadcrumbDefinition = {
  [TRouteId in RegisteredRouteId]: {
    routeId: TRouteId
    Component: ComponentType<RouteBreadcrumbProps<TRouteId>>
  }
}[RegisteredRouteId]

export type RouteBreadcrumbContent = string | RouteBreadcrumbDefinition

export interface RouteBreadcrumb {
  content: RouteBreadcrumbContent
  match: RouteBreadcrumbMatchSnapshot
}

interface ResolvedRouteBreadcrumb {
  contributionItemIndex: number
  content: ReactNode
  href?: string
  isTerminalContribution: boolean
  link?: boolean
  match: RouteBreadcrumbMatchSnapshot
  retargetTo?: RouteRetargetPath
}

export interface RouteBreadcrumbRootProps {
  match: RouteBreadcrumbMatchSnapshot
  retargetTo?: RouteTargetPath
  children: ReactNode
}

export type RouteBreadcrumbRootComponent = ComponentType<RouteBreadcrumbRootProps>

interface RouteBreadcrumbRoot {
  Component: RouteBreadcrumbRootComponent
  match: RouteBreadcrumbMatchSnapshot
  retargetTo?: RouteTargetPath
}

declare module "@tanstack/react-router" {
  interface StaticDataRouteOption {
    breadcrumb?: RouteBreadcrumbContent
    breadcrumbRoot?: RouteBreadcrumbRootComponent
    retargetTo?: RouteRetargetPath
  }
}

interface RouteBreadcrumbMatch {
  routeId?: string
  fullPath?: string
  pathname?: string
  params?: Record<string, string | undefined>
  loaderData?: unknown
  status: string
  staticData?: {
    breadcrumb?: RouteBreadcrumbContent
    breadcrumbRoot?: RouteBreadcrumbRootComponent
    retargetTo?: RouteRetargetPath
  }
}

function matchSnapshot(match: RouteBreadcrumbMatch): RouteBreadcrumbMatchSnapshot {
  if (!match.routeId || !match.fullPath) {
    throw new Error("Breadcrumb matches require a route ID and full path")
  }

  return {
    routeId: match.routeId,
    fullPath: match.fullPath,
    pathname: match.pathname ?? "",
    params: match.params ?? {},
    loaderData: match.loaderData,
    retargetTo: match.staticData?.retargetTo,
  } as RouteBreadcrumbMatchSnapshot
}

export function selectRouteBreadcrumbs(
  matches: readonly RouteBreadcrumbMatch[],
): RouteBreadcrumb[] {
  const successfulMatches = matches.slice(0, firstUnsuccessfulMatchIndex(matches))
  return successfulMatches.flatMap((match) => {
    const content = match.staticData?.breadcrumb
    return content ? [{ content, match: matchSnapshot(match) }] : []
  })
}

function firstUnsuccessfulMatchIndex(matches: readonly RouteBreadcrumbMatch[]) {
  const index = matches.findIndex((match) => match.status !== "success")
  return index === -1 ? matches.length : index
}

function firstDescendantTarget(
  matches: readonly RouteBreadcrumbMatch[],
  rootIndex: number,
  successfulMatchCount: number,
): RouteTargetPath | undefined {
  for (let index = rootIndex + 1; index < successfulMatchCount; index += 1) {
    const match = matches[index]
    if (!match.staticData?.breadcrumb) continue
    return match.staticData.retargetTo ?? match.fullPath
  }

  return undefined
}

function selectRouteBreadcrumbRoot(
  matches: readonly RouteBreadcrumbMatch[],
): RouteBreadcrumbRoot | null {
  const successfulMatchCount = firstUnsuccessfulMatchIndex(matches)
  for (let index = successfulMatchCount - 1; index >= 0; index -= 1) {
    const match = matches[index]
    const Component = match.staticData?.breadcrumbRoot
    if (Component) {
      return {
        Component,
        match: matchSnapshot(match),
        retargetTo: firstDescendantTarget(matches, index, successfulMatchCount),
      }
    }
  }

  return null
}

type ErrorBreadcrumbLabel = "Error" | "Page not found"

interface RouteBreadcrumbSelection {
  status: string
  breadcrumbs: RouteBreadcrumb[]
  root: RouteBreadcrumbRoot | null
  errorBreadcrumb: ErrorBreadcrumbLabel | null
}

interface RouteBreadcrumbRouterState {
  status: string
  matches: readonly RouteBreadcrumbMatch[]
}

export function selectErrorBreadcrumb(
  matches: readonly RouteBreadcrumbMatch[],
): ErrorBreadcrumbLabel | null {
  if (matches.some((match) => match.status === "notFound")) return "Page not found"
  if (matches.some((match) => match.status === "error")) return "Error"
  return null
}

export function resolveRouteBreadcrumbState(
  status: string,
  current: Omit<RouteBreadcrumbSelection, "status">,
  committed: Omit<RouteBreadcrumbSelection, "status">,
): Omit<RouteBreadcrumbSelection, "status"> {
  const hasCommittedChain =
    committed.root !== null ||
    committed.breadcrumbs.length > 0 ||
    committed.errorBreadcrumb !== null
  return status === "pending" && hasCommittedChain ? committed : current
}

function selectRouteBreadcrumbState(state: RouteBreadcrumbRouterState): RouteBreadcrumbSelection {
  return {
    status: state.status,
    breadcrumbs: selectRouteBreadcrumbs(state.matches),
    root: selectRouteBreadcrumbRoot(state.matches),
    errorBreadcrumb: selectErrorBreadcrumb(state.matches),
  }
}

export function useRouteBreadcrumbState(): Omit<RouteBreadcrumbSelection, "status"> {
  const previousSelectionRef = useRef<RouteBreadcrumbSelection | undefined>(undefined)
  const committedStateRef = useRef<Omit<RouteBreadcrumbSelection, "status"> | undefined>(undefined)
  const previousResolvedStateRef = useRef<Omit<RouteBreadcrumbSelection, "status"> | undefined>(
    undefined,
  )
  const selectBreadcrumbState = useCallback((state: RouteBreadcrumbRouterState) => {
    const selection = replaceEqualDeep(
      previousSelectionRef.current,
      selectRouteBreadcrumbState(state),
    )
    previousSelectionRef.current = selection
    const current = {
      breadcrumbs: selection.breadcrumbs,
      root: selection.root,
      errorBreadcrumb: selection.errorBreadcrumb,
    }
    if (selection.status === "idle") committedStateRef.current = current
    const resolved = resolveRouteBreadcrumbState(
      selection.status,
      current,
      committedStateRef.current ?? current,
    )
    const stableResolved = replaceEqualDeep(previousResolvedStateRef.current, resolved)
    previousResolvedStateRef.current = stableResolved
    return stableResolved
  }, [])
  return useRouterState({ select: selectBreadcrumbState })
}

function RouteBreadcrumbResolver({
  breadcrumbs,
  index,
  resolved,
  children,
}: {
  breadcrumbs: readonly RouteBreadcrumb[]
  index: number
  resolved: readonly ResolvedRouteBreadcrumb[]
  children: (breadcrumbs: readonly ResolvedRouteBreadcrumb[]) => ReactElement | null
}): ReactElement | null {
  const breadcrumb = breadcrumbs[index]
  if (!breadcrumb) return children(resolved)

  const continueWith = (content: ReactNode | RouteBreadcrumbItem[] | null) => {
    const items = normalizeRouteBreadcrumbItems(content)
    return (
      <RouteBreadcrumbResolver
        breadcrumbs={breadcrumbs}
        index={index + 1}
        resolved={[
          ...resolved,
          ...items.map((item, itemIndex) => ({
            ...item,
            contributionItemIndex: itemIndex,
            isTerminalContribution:
              index === breadcrumbs.length - 1 && itemIndex === items.length - 1,
            match: breadcrumb.match,
          })),
        ]}
      >
        {children}
      </RouteBreadcrumbResolver>
    )
  }

  if (typeof breadcrumb.content === "string") return continueWith(breadcrumb.content)

  const definition = breadcrumb.content
  if (definition.routeId !== breadcrumb.match.routeId) {
    throw new Error(
      `Expected breadcrumb match ${definition.routeId}, received ${breadcrumb.match.routeId}`,
    )
  }

  const Content = definition.Component as ComponentType<RouteBreadcrumbProps<string, unknown>>
  return (
    <Content match={breadcrumb.match}>{(resolvedContent) => continueWith(resolvedContent)}</Content>
  )
}

function normalizeRouteBreadcrumbItems(
  content: ReactNode | RouteBreadcrumbItem[] | null,
): readonly RouteBreadcrumbItem[] {
  if (content == null) return []
  if (Array.isArray(content) && content.every(isRouteBreadcrumbItem)) return content
  return [{ content }]
}

function isRouteBreadcrumbItem(value: unknown): value is RouteBreadcrumbItem {
  return typeof value === "object" && value !== null && "content" in value
}

function DefaultBreadcrumbRoot({ children }: { children: ReactNode }) {
  return <Breadcrumbs>{children}</Breadcrumbs>
}

export function buildRouteHref(
  to: RouteTargetPath,
  params: Readonly<Record<string, string | undefined>>,
) {
  const { interpolatedPath, isMissingParams } = interpolatePath({ path: to, params })
  if (isMissingParams) throw new Error(`Missing parameters for route target ${to}`)
  return interpolatedPath
}

function ResolvedRouteBreadcrumbsView({
  breadcrumbs,
  root,
  errorBreadcrumb,
}: Omit<RouteBreadcrumbSelection, "status">) {
  return (
    <RouteBreadcrumbResolver breadcrumbs={breadcrumbs} index={0} resolved={[]}>
      {(resolvedBreadcrumbs) => {
        const breadcrumbsWithHrefs = resolvedBreadcrumbs.map((breadcrumb) => ({
          ...breadcrumb,
          href: breadcrumb.retargetTo
            ? buildRouteHref(breadcrumb.retargetTo, breadcrumb.match.params)
            : breadcrumb.match.retargetTo
              ? buildRouteHref(breadcrumb.match.retargetTo, breadcrumb.match.params)
              : breadcrumb.match.pathname || undefined,
        }))
        const items = breadcrumbsWithHrefs.map((breadcrumb) => {
          return (
            <Breadcrumbs.Item
              key={`${breadcrumb.match.routeId}:${breadcrumb.match.pathname}:${breadcrumb.contributionItemIndex}`}
              href={
                breadcrumb.link !== false && (!breadcrumb.isTerminalContribution || errorBreadcrumb)
                  ? breadcrumb.href
                  : undefined
              }
            >
              {breadcrumb.content}
            </Breadcrumbs.Item>
          )
        })
        if (errorBreadcrumb) {
          items.push(
            <Breadcrumbs.Item key="route-error-breadcrumb">{errorBreadcrumb}</Breadcrumbs.Item>,
          )
        }

        if (!root) {
          return items.length > 0 ? <DefaultBreadcrumbRoot>{items}</DefaultBreadcrumbRoot> : null
        }

        const Root = root.Component
        return (
          <Root match={root.match} retargetTo={root.retargetTo}>
            {items}
          </Root>
        )
      }}
    </RouteBreadcrumbResolver>
  )
}

export function RouteBreadcrumbs() {
  const routeBreadcrumbState = useRouteBreadcrumbState()
  return <ResolvedRouteBreadcrumbsView {...routeBreadcrumbState} />
}
