  --marvin-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --marvin-font-heading: "Entire Headline", ui-sans-serif, system-ui, sans-serif;
  --marvin-font-code: "Entire Mono", ui-monospace, monospace;
  --marvin-radius-control: 8px;
