  --sidebar: var(--marvin-bg);
  --hover: var(--marvin-surface);
  --danger: #9a3434;
  --success: #44624e;
  --shadow: 0 16px 48px rgb(0 0 0 / .12);
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --marvin-bg: #161616;
    --marvin-surface: #222222;
    --marvin-raised: #1c1c1c;
    --marvin-text: #f3f3f3;
