/* Entire app shell: 52px header, 272px navigation, 36px rows. The app uses
   the full viewport; the marketing site's centered rails belong to login. */
.app-layout {
  --sidebar-width: 272px;
  --sidebar-hover: rgb(0 0 0 / .035);
  --sidebar-selected: rgb(0 0 0 / .06);
  display: block;
  max-width: none;
  border: 0;
  position: relative;
}
@media (prefers-color-scheme: dark) {
  .app-layout {
    --sidebar-hover: rgb(255 255 255 / .06);
    --sidebar-selected: rgb(255 255 255 / .08);
  }
}
.app-layout .workspace { height: 100%; margin-left: 0; transition: margin-left 150ms ease-out; }
.sidebar-pinned .workspace { margin-left: var(--sidebar-width); }
.app-layout .workspace-header { height: 52px; padding-inline: 16px; }
.app-sidebar {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--sidebar-width);
  z-index: 40;
  display: grid;
  grid-template-rows: 52px minmax(0, 1fr);
  background: var(--marvin-bg);
  border-radius: 12px; box-shadow: var(--shadow);
}
.account-menu-heading { padding: 10px 12px; display: grid; gap: 3px; }
.account-menu-heading strong { font-size: 14px; font-weight: 500; overflow-wrap: anywhere; }
.account-menu-heading span { color: var(--marvin-muted); font-size: 12px; }
.account-menu-content [role=menuitem] {
  display: flex; align-items: center; gap: 10px; width: 100%; min-height: 36px;
  padding: 8px 12px; border-radius: 8px; color: var(--marvin-text);
  font-size: 14px; line-height: 20px; text-decoration: none; text-align: left;
}
.account-menu-content [role=menuitem]:hover, .account-menu-content [role=menuitem]:focus {
  background: var(--hover); outline: none;
}
.account-menu-content [role=menuitem] svg { color: var(--marvin-muted); }
.account-menu-content .account-external { margin-left: auto; }
.account-menu-separator { height: 1px; margin: 4px; background: var(--marvin-rule); }

.pet-status-icon { display: none; }
