function historyReplace(id:string){history.replaceState({},'','/app/'+id);}
import type { ReactNode } from "react"
import { twMerge } from "tailwind-merge"

import { FloatingShell } from "@/components/FloatingShell"

interface SettingsPageContentProps {
  title: string
  description?: ReactNode
  notice?: ReactNode
  action?: ReactNode
  children: ReactNode
}

export function SettingsPageBody({ children }: { children: ReactNode }) {
  return <div className="mx-auto w-full max-w-3xl space-y-8 px-4 py-6">{children}</div>
}

export function SettingsPageHeading({ title, metadata }: { title: string; metadata: ReactNode }) {
  return (
    <div className="min-w-0">
      <h1 className="truncate font-headline text-2xl leading-7 font-semibold tracking-[-0.44px] text-default">
        {title}
      </h1>
      <div className="mt-1 text-sm text-muted">{metadata}</div>
    </div>
  )
}

export function SettingsPageContent({
  title,
  description,
  notice,
  action,
  children,
}: SettingsPageContentProps) {
  return (
    <div className="mx-auto w-full max-w-3xl space-y-8 px-4 py-6">
      <div>
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h1 className="text-xl font-bold text-default">{title}</h1>
            {description && <p className="mt-3 text-sm text-muted">{description}</p>}
          </div>
          {action && <div className="shrink-0">{action}</div>}
        </div>
        {notice && (
          <div className="mt-2 rounded border border-default bg-raised p-3 text-sm text-muted">
            {notice}
          </div>
        )}
      </div>
      {children}
    </div>
  )
}

export function SettingsSection({
  title,
  action,
  controls,
  children,
}: {
  title: string
  action?: ReactNode
  controls?: ReactNode
  children: ReactNode
}) {
  if (controls) {
    return (
      <section>
        <div className="mb-3 grid grid-cols-[minmax(0,1fr)_auto] gap-x-4 gap-y-3">
          <h2 className="text-base font-semibold text-default">{title}</h2>
          {action ? <div className="self-start justify-self-end">{action}</div> : null}
          <div className="col-span-2 col-start-1 row-start-2 min-w-0 sm:col-span-1">{controls}</div>
        </div>
        {children}
      </section>
    )
  }

  return (
    <section>
      <div className="mb-2 flex items-center justify-between gap-4">
        <h2 className="text-base font-semibold text-default">{title}</h2>
        {action}
      </div>
      {children}
    </section>
  )
}

interface SettingsCardProps {
  children: ReactNode
  className?: string
  innerClassName?: string
}

export function SettingsCard({ children, className, innerClassName }: SettingsCardProps) {
  return (
    <FloatingShell
      className={twMerge("-mx-4 rounded-xl", className)}
      innerClassName={twMerge(
        "overflow-hidden rounded-[calc(var(--radius-xl)-1px)]",
        innerClassName,
      )}
    >
      {children}
    </FloatingShell>
  )
}
