x}.stick-label b{font-size:16px}.stick-label span{font-size:11px;color:var(--marvin-muted)}.analog-stick{width:190px;height:190px;border-radius:50%;background:radial-gradient(circle at 50% 50%,var(--panel) 0 34%,var(--marvin-surface) 35% 100%);border:1px solid var(--marvin-rule);box-shadow:inset 0 0 0 18px color-mix(in srgb,var(--marvin-bg) 30%,transparent);display:grid;place-items:center;touch-action:none;cursor:grab;position:relative}.analog-stick.active{cursor:grabbing;border-color:var(--marvin-link);box-shadow:0 0 0 4px color-mix(in srgb,var(--marvin-link) 13%,transparent),inset 0 0 0 18px color-mix(in srgb,var(--marvin-bg) 30%,transparent)}.analog-stick:before,.analog-stick:after{content:'';position:absolute;background:var(--marvin-rule);opacity:.55}.analog-stick:before{width:1px;height:145px}.analog-stick:after{height:1px;width:145px}.analog-stick i{width:66px;height:66px;border-radius:50%;background:var(--marvin-link);box-shadow:0 5px 18px #0004;z-index:1;transition:transform .05s}.remote-safety{text-align:center;color:var(--marvin-muted);font-size:12px;margin:44px auto 0;max-width:500px;line-height:1.5}
