/* Quiet raised surfaces, indigo actions, and consistent controls. */
.button, .new-chat, .icon-button, .send-button, .settings-nav button,
.history-list button, .sidebar-bottom > a, .sidebar-bottom > button,
.field input, .field select, .repository-panel select, .eye-design-card select,
.voice-action, .voice-end, .remote-speech-composer {
  border-radius: var(--marvin-radius-control);
}
.button { min-height: var(--marvin-target-size); font-size: 14px; font-weight: 500; line-height: 20px; }
.button.primary:hover { filter: none; background: var(--marvin-accent-hover); }
.button.secondary { box-shadow: 0 1px 2px rgb(0 0 0 / .04); }
.dialog, .setting-card, .repo-card, .connect-card, .suggestions button,
.composer, .voice-composer, .voice-presence, .instructions, .remote-speech,
.entire-auth-step, .connector-fallback, .autonomous-switch {
  border-radius: var(--marvin-radius-panel);
}
.dialog { background: var(--panel); }
.dialog-header { background: var(--panel); min-height: 64px; }
.settings-nav { background: var(--marvin-bg); }
.settings-nav button.active, .history-list button.active {
  color: var(--marvin-link); background: var(--marvin-accent-subtle);
}
.suggestions button, .connect-card, .composer, .voice-presence, .voice-composer,
.remote-speech { background: var(--panel); border-color: var(--marvin-rule); box-shadow: none; }
.suggestions button:hover { transform: none; background: var(--hover); border-color: var(--marvin-accent); }
.composer:focus-within, .voice-composer:focus-within {
  border-color: var(--marvin-accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--marvin-accent) 12%, transparent);

item.aggregated_output:
  {modal==='settings'&&<Dialog title="Settings" onClose={()=>{setModal(null);setConfirmUnlink(false);}} wide><div className="settings-layout"><nav className="settings-nav" aria-label="Settings sections">{[{name:'Connections',icon:Link2},{name:'Desktop Pet',icon:Wifi},{name:'Voice and models',icon:Volume2},{name:'Privacy and history',icon:Shield}].map(t=><button key={t.name} className={settingsTab===t.name?'active':''} onClick={()=>{setSettingsTab(t.name);setConfirmUnlink(false);}}><t.icon size={16}/>{t.name}</button>)}</nav><div className="settings-pane">
   {settingsTab==='Connections'&&<><p className="eyebrow">REPOSITORY CONTEXT</p><h3>A connection to your work.</h3><p className="muted">Entire brings together code, checkpoints, and the context behind your decisions.</p><div className="setting-card entire-connection-card">
    <div className="setting-card-title"><div className="connection-logo" aria-hidden="true"/><div><strong>Entire</strong><small>{settings?.entireState==='connected'?(settings.entireStatus==='configuration_error'?'Connection needs attention':`Connected · ${settings.entireConnection?.method==='connector'?'local connector':'cloud sign-in'} · read-only`):settings?.entireState==='fixture'?'Sample connection active':'Not connected'}</small></div>{settings?.entireState==='connected'&&settings.entireStatus==='connected'&&<Check size={18}/>}</div>
    {settings?.entireState==='connected'?<><p>Marvin checks your repository access before reading. Change repositories in the conversation header. Your Entire credentials stay separate from your Marvin account.</p><button className="button secondary full" onClick={()=>void entire('connect')}>Check connection</button><button className="text-button" onClick={()=>void entire('disconnect')}>Disconnect Entire</button></>:settings?.entireState==='fixture'?<><p>Sample repository data is active for this preview.</p><button className="button secondary full" onClick={()=>void entire('disconnect')}>Disconnect sample data</button></>:<>
     <p>{entireDescription(settings)}</p>
     {entireLogin?<div className="entire-auth-step" role="status"><strong>{entireLogin.status==='connected'?'Entire is connected':entireLogin.status==='failed'?'Sign-in could not finish':'Finish signing in to Entire'}</strong>{entireLogin.userCode&&<div className="entire-device-code"><span>Code</span><code>{entireLogin.userCode}</code></div>}{entireLogin.verificationUri&&<a className="button primary full" href={entireLogin.verificationUri} target="_blank" rel="noreferrer">Open Entire sign-in <ExternalLink size={15}/></a>}{entireLogin.error&&<p className="notice">{entireLogin.error}</p>}{['starting','waiting'].includes(entireLogin.status)&&<button className="text-button" onClick={()=>void cancelEntireLogin()}>Cancel sign-in</button>}{['failed','cancelled'].includes(entireLogin.status)&&<button className="button primary full" onClick={()=>void startEntireLogin()}>Try again</button>}</div>:settings?.entireMethods?.hosted&&<button className="button primary full" onClick={()=>void startEntireLogin()}>Sign in to Entire</button>}
     {settings?.entireMethods?.connector&&<div className="connector-fallback"><div><strong>Working from your own computer?</strong><p>Use the small Marvin connector when cloud sign-in cannot reach the repositories available to your local Entire CLI.</p></div>{connectorPairing?<div className="connector-pairing" role="status"><div><span>Marvin URL</span><code>{connectorPairing.serverUrl}</code></div><div><span>One-time code</span><code>{connectorPairing.token}</code></div><p>Open the Marvin Entire Connector on your computer and enter these two values. This code expires shortly and can be used once.</p></div>:<button className="button secondary full" onClick={()=>void createConnectorPairing()}>Set up local connector</button>}</div>}
     <a className="text-button" href="https://docs.entire.io/cli-reference/login" target="_blank" rel="noreferrer">Entire login documentation <ExternalLink size={13}/></a>{config.development&&<button className="button secondary full" onClick={()=>void entire('fixture')}>Explore a sample repository <ArrowRight size={16}/></button>}
    </>}{settings?.entireError&&<p className="notice">{settings.entireError}</p>}
   </div></>}
   {settingsTab==='Desktop Pet'&&<>
    <p className="eyebrow">YOUR PHYSICAL COMPANION</p><h3>{settings?.body?'Meet your Desktop Pet.':'Bring the conversation to life.'}</h3>{unlinkNotice&&<p className="notice" role="status">{unlinkNotice}</p>}
    {!settings?.body?<><div className="settings-robot"><Face large/></div><p className="muted">Link a Desktop Pet whenever you’re ready. Your conversations and repository context will come with you.</p><button className="button primary full" onClick={()=>{setModal(null);setUnlinkNotice('');setSetup('new');}}>Set up your Desktop Pet <ArrowRight size={16}/></button><p className="fine-print">Your browser may label a previously used Desktop Pet “Paired.” Setup verifies its account link after connecting.</p></>:<>
     <div className="setting-card"><div className="robot-summary"><Face/><div><strong>Desktop Pet</strong><small>{settings.body.simulated?'Simulated Desktop Pet · preview only':robotOnline?'Online':'Offline'}</small></div><span className="badge">Linked</span></div><dl className="device-details"><dt>Network</dt><dd>{settings.body.network}</dd><dt>Device</dt><dd><code>{settings.body.device_id}</code></dd></dl><button className="button secondary full" onClick={()=>{setModal(null);setSetup('change');}}><Wifi size={16}/>Change Wi-Fi<ChevronRight size={15}/></button><p className="fine-print">Moved somewhere new? Change the network while keeping the same Desktop Pet linked.</p></div>
     <div className="setting-card pet-audio-card"><div className="setting-card-title"><div><strong>Sound and microphone</strong><small>{petAudio?'Synced with your Desktop Pet':robotOnline?'Audio controls require a firmware update':'Connect your Desktop Pet to change these controls'}</small></div>{petAudio?.muted?<MicOff size={18}/>:<Volume2 size={18}/>}</div>{petAudio?<PetAudioControls value={petAudio} onChange={updatePetAudio}/>:<PetAudioControls value={{volume:60,muted:false}} onChange={()=>{}} disabled/>}<div className="pet-volume pet-microphone-gain"><Mic size={18}/><label><span>Microphone sensitivity {petAudio?.microphoneGainDb!==undefined?`${petAudio.microphoneGainDb} dB`:''}</span><input aria-label="Desktop Pet microphone sensitivity" type="range" min="0" max="36" step="6" value={petAudio?.microphoneGainDb??30} disabled={petAudio?.microphoneGainDb===undefined} onChange={e=>petAudio&&updatePetAudio({...petAudio,microphoneGainDb:Number(e.target.value)},true)}/></label></div>{petAudio&&petAudio.microphoneGainDb===undefined&&<p className="fine-print">Update your Desktop Pet firmware to adjust microphone sensitivity.</p>}<div className="pet-conversation-settings"><strong>Conversation</strong><label className="pet-followup"><span>Listen for a reply <b>{petAudio?.followupSeconds===0?'Off':`${petAudio?.followupSeconds??5} seconds`}</b></span><input aria-label="Desktop Pet follow-up window" type="range" min="0" max="30" step="1" value={petAudio?.followupSeconds??5} disabled={petAudio?.followupSeconds===undefined} onChange={e=>petAudio&&updatePetAudio({...petAudio,followupSeconds:Number(e.target.value)},true)}/><small>After Marvin finishes speaking, you can reply without saying “Hey Marvin.”</small></label><label className="pet-playback-toggle"><span><b>Talk while Marvin speaks</b><small>Uses echo cancellation. Experimental: Marvin may mistake its own voice for yours.</small></span><input aria-label="Allow Desktop Pet microphone during playback" type="checkbox" checked={petAudio?.allowPlaybackMic??false} disabled={petAudio?.allowPlaybackMic===undefined} onChange={e=>petAudio&&updatePetAudio({...petAudio,allowPlaybackMic:e.target.checked})}/></label>{petAudio&&petAudio.followupSeconds===undefined&&<p className="fine-print">Update your Desktop Pet firmware to use conversation controls.</p>}</div><p className="fine-print">The Pet’s side buttons adjust volume and mute. Muting also disables its wake word until you unmute it.</p></div>
     <div className="setting-card eye-design-card"><div className="setting-card-title"><div><strong>Eye design</strong><small>{eyeSettings?'Saved on your Desktop Pet':robotOnline?'Eye designs require a firmware update':'Connect your Desktop Pet to change its eyes'}</small></div><Eye size={18}/></div><label><span className="sr-only">Desktop Pet eye design</span><select aria-label="Desktop Pet eye design" value={eyeSettings?.design??'classic'} disabled={!eyeSettings} onChange={event=>void updateEyeSettings({design:event.target.value as EyeSettings['design']})}><option value="classic">Classic · white with black center</option><option value="solid">Solid · pupil-free</option><option value="friendly">Friendly · smile blink</option></select></label><p className="fine-print">The selection is stored on the Pet and restored whenever it boots.</p></div>
     <div className="setting-card head-calibration-card"><div className="setting-card-title"><div><strong>Head servo calibration</strong><small>{headCalibration?'Saved on your Desktop Pet':robotOnline?'Calibration requires a firmware update':'Connect your Desktop Pet to calibrate its head'}</small></div><SlidersHorizontal size={18}/></div>{headCalibration?<><p>Adjust the neutral position and direction for each head servo. The head follows the sliders; Save keeps the new center after restart.</p><HeadCalibrationControls value={headCalibration} onSave={updateHeadCalibration} onPreview={previewHeadCalibration} previewAvailable={headCalibrationPreview}/>{!headCalibrationPreview&&<p className="fine-print">Update your Desktop Pet firmware to preview calibration while moving the sliders.</p>}<p className="fine-print">Keep Marvin on a clear surface and stay within reach while calibrating.</p></>:<fieldset className="head-calibration-disabled" disabled><HeadCalibrationControls value={{yawCenter:90,pitchCenter:90,yawReversed:true,pitchReversed:true}} onSave={async()=>{}} previewAvailable={false}/></fieldset>}</div>
     <div className="ownership-section">{confirmUnlink?<><h4>Unlink this Desktop Pet?</h4><p>Your Desktop Pet loses access to your account immediately. <strong>Your chats and Entire connection stay with you.</strong> If your Desktop Pet is offline, its local account link will be cleared during the next setup. Reset it before giving it to someone else if you also want to erase Wi-Fi settings.</p><div className="wizard-actions"><button className="button secondary" onClick={()=>setConfirmUnlink(false)}>Keep linked</button><button className="button danger" onClick={()=>void unlink()}>Unlink Desktop Pet</button></div></>:<><h4>Account link</h4><p>Unlink your Desktop Pet if you’re replacing it or giving it to someone else.</p><button className="text-button danger-text" onClick={()=>setConfirmUnlink(true)}><Unplug size={15}/>Unlink Desktop Pet</button></>}</div>
