/* Quiet raised surfaces, indigo actions, and consistent controls. */
.button, .new-chat, .icon-button, .send-button, .settings-nav button,
.history-list button, .sidebar-bottom > a, .sidebar-bottom > button,
.field input, .field select, .repository-panel select, .eye-design-card select,
.voice-action, .voice-end, .remote-speech-composer {
  border-radius: var(--marvin-radius-control);
}
.button { min-height: var(--marvin-target-size); font-size: 14px; font-weight: 500; line-height: 20px; }
.button.primary:hover { filter: none; background: var(--marvin-accent-hover); }
.button.secondary { box-shadow: 0 1px 2px rgb(0 0 0 / .04); }
.dialog, .setting-card, .repo-card, .connect-card, .suggestions button,
.composer, .voice-composer, .voice-presence, .instructions, .remote-speech,
.entire-auth-step, .connector-fallback, .autonomous-switch {
  border-radius: var(--marvin-radius-panel);
}
.dialog { background: var(--panel); }
.dialog-header { background: var(--panel); min-height: 64px; }
.settings-nav { background: var(--marvin-bg); }
.settings-nav button.active, .history-list button.active {
  color: var(--marvin-link); background: var(--marvin-accent-subtle);
}
.suggestions button, .connect-card, .composer, .voice-presence, .voice-composer,
.remote-speech { background: var(--panel); border-color: var(--marvin-rule); box-shadow: none; }
.suggestions button:hover { transform: none; background: var(--hover); border-color: var(--marvin-accent); }
.composer:focus-within, .voice-composer:focus-within {
  border-color: var(--marvin-accent);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--marvin-accent) 12%, transparent);

