import type { ReactNode } from "react"
import { twMerge } from "tailwind-merge"

import { FloatingShell } from "@/components/FloatingShell"

interface SettingsPageContentProps {
  title: string
  description?: ReactNode
  notice?: ReactNode
  action?: ReactNode
  children: ReactNode
}

export function SettingsPageBody({ children }: { children: ReactNode }) {
  return <div className="mx-auto w-full max-w-3xl space-y-8 px-4 py-6">{children}</div>
}

export function SettingsPageHeading({ title, metadata }: { title: string; metadata: ReactNode }) {
  return (
    <div className="min-w-0">
      <h1 className="truncate font-headline text-2xl leading-7 font-semibold tracking-[-0.44px] text-default">
        {title}
      </h1>
      <div className="mt-1 text-sm text-muted">{metadata}</div>
    </div>
  )
}

export function SettingsPageContent({
  title,
  description,
  notice,
  action,
  children,
}: SettingsPageContentProps) {
  return (
    <div className="mx-auto w-full max-w-3xl space-y-8 px-4 py-6">
      <div>
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h1 className="text-xl font-bold text-default">{title}</h1>
            {description && <p className="mt-3 text-sm text-muted">{description}</p>}
          </div>
          {action && <div className="shrink-0">{action}</div>}
        </div>
        {notice && (
          <div className="mt-2 rounded border border-default bg-raised p-3 text-sm text-muted">
            {notice}
          </div>
        )}
      </div>
      {children}
    </div>
  )
}

export function SettingsSection({
  title,
  action,
  controls,
  children,
}: {
  title: string
  action?: ReactNode
  controls?: ReactNode
  children: ReactNode
}) {
  if (controls) {
    return (
      <section>
        <div className="mb-3 grid grid-cols-[minmax(0,1fr)_auto] gap-x-4 gap-y-3">
          <h2 className="text-base font-semibold text-default">{title}</h2>
          {action ? <div className="self-start justify-self-end">{action}</div> : null}
          <div className="col-span-2 col-start-1 row-start-2 min-w-0 sm:col-span-1">{controls}</div>
        </div>
        {children}
      </section>
    )
  }

  return (
    <section>
      <div className="mb-2 flex items-center justify-between gap-4">
        <h2 className="text-base font-semibold text-default">{title}</h2>
        {action}
      </div>
      {children}
    </section>
  )
}

interface SettingsCardProps {
  children: ReactNode
  className?: string
  innerClassName?: string
}

export function SettingsCard({ children, className, innerClassName }: SettingsCardProps) {
  return (
    <FloatingShell
      className={twMerge("-mx-4 rounded-xl", className)}
      innerClassName={twMerge(
        "overflow-hidden rounded-[calc(var(--radius-xl)-1px)]",
        innerClassName,
      )}
    >
      {children}
    </FloatingShell>
  )
}
import {useEffect,useState} from 'react';
import {Download,Shield} from 'lucide-react';
import {api} from './api';
export function PrivacyPanel({onError}:{onError:(error:unknown)=>void}){
 const [days,setDays]=useState<string>(''),[confirm,setConfirm]=useState(false),[phrase,setPhrase]=useState(''),[busy,setBusy]=useState(false),[saved,setSaved]=useState(false);
 useEffect(()=>{void api<{retention_days:number|null}>('/account/privacy').then(p=>setDays(p.retention_days===null?'forever':String(p.retention_days))).catch(onError);},[onError]);
 async function retention(value:string){setBusy(true);setSaved(false);try{await api('/account/privacy','PATCH',{retentionDays:value==='forever'?null:Number(value)});setDays(value);setSaved(true);}catch(e){onError(e);}finally{setBusy(false);}}
 async function remove(){setBusy(true);try{await api('/account','DELETE',{confirmation:phrase});location.assign('/login');}catch(e){onError(e);setBusy(false);}}
 return <><p className="eyebrow">YOUR SPACE, YOUR CONTEXT</p><h3>Your conversations, your choice.</h3><div className="setting-card"><Shield size={22}/><h4>What Marvin keeps</h4><p>Your server saves messages and voice transcripts for continuity. Raw audio is not stored by Marvin. During a voice session, audio is sent to the configured provider.</p><a className="button secondary" href="/api/account/export/download" download><Download size={16}/>Download conversations</a><p className="fine-print">Includes your messages and replies in a portable data file. Credentials and Wi-Fi settings are excluded.</p></div><div className="setting-card"><label className="field">Keep conversation history<select value={days} disabled={busy||!days} onChange={e=>void retention(e.target.value)}><option value="" disabled>Loading…</option><option value="forever">Until I delete my account</option><option value="30">30 days</option><option value="90">90 days</option><option value="365">One year</option></select></label><p className="fine-print">Older messages and their saved summaries are removed during regular maintenance. Server backups and provider records follow their own retention policies.</p>{saved&&<p role="status">Retention preference saved.</p>}</div><div className="ownership-section"><h4>Delete your Marvin account</h4>{confirm?<><p>This permanently deletes your saved conversations and disconnects your Desktop Pet from this account. It does not erase an offline Desktop Pet or delete your Entire or GitHub account.</p><label className="field">Type DELETE MY ACCOUNT to confirm<input value={phrase} onChange={e=>setPhrase(e.target.value)} autoComplete="off"/></label><div className="wizard-actions"><button className="button secondary" disabled={busy} onClick={()=>{setConfirm(false);setPhrase('');}}>Keep my account</button><button className="button danger" disabled={busy||phrase!=='DELETE MY ACCOUNT'} onClick={()=>void remove()}>{busy?'Deleting…':'Delete account'}</button></div></>:<><p>Download your conversations first if you want to keep a copy.</p><button className="text-button danger-text" onClick={()=>setConfirm(true)}>Delete my account</button></>}</div></>;
}
