test('repository explorer renders provenance, safe snippets, pagination and recoverable errors',async({page})=>{
 // Recorded UI responses exercise rendering; this does not claim a live Entire service test.
 await page.route('**/api/settings',async route=>{const response=await route.fetch();await route.fulfill({json:{...await response.json(),entireState:'connected',entireAvailable:true,repositories:[{id:'entire_test',name:'test/repository',capabilities:['summary','source','search','history']}]}});});
