.dialog{color:var(--marvin-text);background:var(--marvin-bg);border:1px solid var(--marvin-rule);padding:0;border-radius:10px;width:min(560px,calc(100vw - 32px));max-height:calc(100dvh - 48px);box-shadow:var(--shadow)}
.dialog::backdrop{background:rgb(0 0 0 / .3);backdrop-filter:blur(3px)}
.dialog.wide{width:min(800px,calc(100vw - 32px))}
.dialog-header{display:flex;justify-content:space-between;align-items:center;padding:19px 25px;border-bottom:1px solid var(--marvin-rule);position:sticky;top:0;background:var(--marvin-bg);z-index:2}
.dialog-header h2{font-size:23px}
.setup-content{padding:25px 32px 32px}
.stepper{display:flex;justify-content:space-between;padding:0;margin:0 0 27px;list-style:none;gap:7px}
.stepper li{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--marvin-muted)}
.stepper li>span{border:1px solid var(--marvin-rule);width:19px;height:19px;border-radius:50%;display:grid;place-items:center;font-size:9px}
.stepper li.current{color:var(--marvin-link)}
.stepper li.current>span{background:var(--marvin-accent-subtle);border-color:var(--marvin-link)}
.setup-content>h3{text-align:center;font-size:27px}
.setup-content>.muted{text-align:center;font-size:15px;margin:0 0 23px}
.dialog{width:calc(100vw - 20px);max-height:calc(100dvh - 20px);border-radius:8px}
.dialog-header{padding:15px 18px}
.dialog-header h2{font-size:22px}
.setup-content{padding:22px}
.stepper li{font-size:9px;gap:4px}
.stepper li>span{width:17px;height:17px}
.stepper{gap:4px}
.setup-content>h3{font-size:25px}

.dialog{animation:dialog-enter 180ms cubic-bezier(.2,.8,.2,1) both}
.dialog::backdrop{animation:backdrop-enter 180ms ease-out both}
.dialog.is-closing{animation:dialog-exit 180ms cubic-bezier(.4,0,1,1) both;pointer-events:none}
.dialog.is-closing::backdrop{animation:backdrop-exit 180ms ease-in both}

